import{f as l,ag as r,o as i,s as a}from"./chunks/framework.D85dHE_g.js";const c=JSON.parse('{"title":"安全生产法律法规","description":"","frontmatter":{"title":"安全生产法律法规","created":"2026-09-10T00:00:00.000Z","updated":"2026-09-11T00:00:00.000Z","tags":["注册安全工程师","法规"],"status":"带学习更新"},"headers":[],"relativePath":"关于工作/注册安全/安全生产法律法规.md","filePath":"关于工作/注册安全/安全生产法律法规.md","lastUpdated":1790496109000}'),n={name:"关于工作/注册安全/安全生产法律法规.md"};function o(e,t,s,g,h,d){return r(),i("div",null,t[0]||(t[0]=[a(`<h1 id="安全生产法律法规" tabindex="-1">安全生产法律法规 <a class="header-anchor" href="#安全生产法律法规" aria-label="Permalink to &quot;安全生产法律法规&quot;">​</a></h1><h2 id="第一章-安全生产相关国家政策" tabindex="-1">第一章 安全生产相关国家政策 <a class="header-anchor" href="#第一章-安全生产相关国家政策" aria-label="Permalink to &quot;第一章 安全生产相关国家政策&quot;">​</a></h2><h3 id="_1-领导人讲话与相关文件" tabindex="-1">1.领导人讲话与相关文件 <a class="header-anchor" href="#_1-领导人讲话与相关文件" aria-label="Permalink to &quot;1.领导人讲话与相关文件&quot;">​</a></h3><ol><li><p>坚持以人民为中心：<strong>依法保障人民权益</strong></p></li><li><p>安全生产红线： <strong>不能牺牲人民的生命</strong></p></li><li><p>20大报告指出安全治理模式向<strong>事前预防</strong>转型</p></li></ol><h3 id="_2-有关安全生产的重要文件" tabindex="-1">2.有关安全生产的重要文件 <a class="header-anchor" href="#_2-有关安全生产的重要文件" aria-label="Permalink to &quot;2.有关安全生产的重要文件&quot;">​</a></h3><ol><li><strong>党政主要负责人</strong>是本地区<strong>安全生产第一责任人</strong></li><li>地方各级安委员会的<strong>主任</strong>由<strong>政府的主要负责人</strong>来担任</li><li><strong>谁管谁负责</strong>：企业全员安全生产由<strong>单位全面责任</strong>；企业全员生产安全生产责任由法定代表人和实际控制人共同安全生产第一责任人</li><li>高危项目实行一票否决</li><li>一般隐患、<strong>重大隐患</strong>企业职代会实行‘<strong>双报告</strong>’制度向<strong>负有安全生产职责的部门</strong></li><li><strong>企业</strong>富有安全责任、管理、投入、培训和应急救援‘五到位’</li><li>宣传‘七进’：进企业、进学校、进机关、进社区、进农村、进家庭、进公共场所</li></ol><h2 id="第二章-法的形式及效力层级" tabindex="-1">第二章 法的形式及效力层级 <a class="header-anchor" href="#第二章-法的形式及效力层级" aria-label="Permalink to &quot;第二章 法的形式及效力层级&quot;">​</a></h2><h3 id="_1-法的形式判别" tabindex="-1">1.法的形式判别 <a class="header-anchor" href="#_1-法的形式判别" aria-label="Permalink to &quot;1.法的形式判别&quot;">​</a></h3><blockquote><p>法律--法、民法典<br> 法规--条例、特别规定<br> 规章--规定、办法、实施细则</p></blockquote><p>行政法规和地方性法规：有地方的为地方性 规章和地方性规章</p><h3 id="_2-法的形式及制定部门与效力" tabindex="-1">2.法的形式及制定部门与效力 <a class="header-anchor" href="#_2-法的形式及制定部门与效力" aria-label="Permalink to &quot;2.法的形式及制定部门与效力&quot;">​</a></h3><blockquote><p>同一机关： 特别&gt;一般、新&gt;旧<br> 不同机关制定：上位法&gt;下位法</p></blockquote><p>①宪法&gt;法律&gt;行政法规和地方性法规<br> ②地方性法规&gt;地方政府规章<br> ③地方性法规=部门规章<br> ④部门规章=地方政府规章</p><h2 id="第三章-安全生产法-15分" tabindex="-1">第三章 安全生产法 15分 <a class="header-anchor" href="#第三章-安全生产法-15分" aria-label="Permalink to &quot;第三章 安全生产法 15分&quot;">​</a></h2><h3 id="_1-安全生产法的基本规定" tabindex="-1">1.安全生产法的基本规定 <a class="header-anchor" href="#_1-安全生产法的基本规定" aria-label="Permalink to &quot;1.安全生产法的基本规定&quot;">​</a></h3><h4 id="_1-1安全生产法适用范围及工作机制" tabindex="-1">1.1安全生产法适用范围及工作机制 <a class="header-anchor" href="#_1-1安全生产法适用范围及工作机制" aria-label="Permalink to &quot;1.1安全生产法适用范围及工作机制&quot;">​</a></h4><p>特殊不适用 ：消防脚痛喝伏特加 (消防交通核辐<u>特+</u>)看是否有规定，有就不适合，没有就适合 有规定按规定，无规定适用《安全生产法》</p><h4 id="_1-2主要负责人的职责" tabindex="-1">1.2主要负责人的职责 <a class="header-anchor" href="#_1-2主要负责人的职责" aria-label="Permalink to &quot;1.2主要负责人的职责&quot;">​</a></h4><p>生产经营单位全面负责<br> 安全生产费用：根据规定提取，传款专用</p><h4 id="_1-3政府职责-安全生产监管职责" tabindex="-1">1.3政府职责（安全生产监管职责） <a class="header-anchor" href="#_1-3政府职责-安全生产监管职责" aria-label="Permalink to &quot;1.3政府职责（安全生产监管职责）&quot;">​</a></h4><p>政府：监管、协调、解决（乡镇只有协助）<br> 工会：监督、提意见</p><h3 id="_2-生产经营单位的安全生产保障-高分值10左右" tabindex="-1">2.生产经营单位的安全生产保障 （高分值10左右） <a class="header-anchor" href="#_2-生产经营单位的安全生产保障-高分值10左右" aria-label="Permalink to &quot;2.生产经营单位的安全生产保障 （高分值10左右）&quot;">​</a></h3><h4 id="_2-1主要负责人和安全管理人员的责任" tabindex="-1">2.1主要负责人和安全管理人员的责任 <a class="header-anchor" href="#_2-1主要负责人和安全管理人员的责任" aria-label="Permalink to &quot;2.1主要负责人和安全管理人员的责任&quot;">​</a></h4><p>主要负责人：</p><ul><li>建章立制</li><li>组织制定并实施：制定</li><li>安全生产投入有效实施</li><li>报告：及时、如实报告生产安全事故</li></ul><p>安全生产管理人员（或机构）</p><ul><li>组织或参与：拟定</li><li>组织开展：培训、记录</li><li>排查隐患、提建议</li><li>督促落实整改措施</li></ul><h4 id="_2-2安全管理机构与管理人员的配备" tabindex="-1">2.2安全管理机构与管理人员的配备 <a class="header-anchor" href="#_2-2安全管理机构与管理人员的配备" aria-label="Permalink to &quot;2.2安全管理机构与管理人员的配备&quot;">​</a></h4><ul><li><p>考点一<br> 定性：危运建金矿--机构或专职<br> 定量：大于100--机构或专职、小于等于100专职或兼职</p><pre><code>注册安全工程师的配备：
危金矿--应当配备（拓展：任免需要告知负由安全监督部门、考核合格）
其他--鼓励
</code></pre></li><li><p>考点二<br><strong>安全管理人员</strong><br> 发现安全问题：处理--不能处理--本单位有关负责人<br> 发现安全重大隐患：及时报告（向负责人）--不处理--向负有相关安全部门报告</p></li></ul><h4 id="_2-3从业人员的教育培训" tabindex="-1">2.3从业人员的教育培训 <a class="header-anchor" href="#_2-3从业人员的教育培训" aria-label="Permalink to &quot;2.3从业人员的教育培训&quot;">​</a></h4><p>从业人员（所有）：单位对从业培训（需合格） 劳务派遣：劳务公司必要安全培训、用工单位对从业培训 实习生：从业培训</p><h4 id="_2-4建设项目的规定" tabindex="-1">2.4建设项目的规定 <a class="header-anchor" href="#_2-4建设项目的规定" aria-label="Permalink to &quot;2.4建设项目的规定&quot;">​</a></h4><ol><li>安全评价 危金矿：应当按照国家有关规定进行<strong>安全评价</strong></li><li>安全实施‘三同时’ 三同时：同时设计、同时施工和同时投入生产和使用</li></ol><p>估--概（设计）--预--结--决</p><ol start="3"><li>安全实施设计审查与验收</li></ol><table tabindex="0"><thead><tr><th>对象</th><th>设计</th><th>审查</th><th>施工</th><th>验收</th><th>监督核查</th></tr></thead><tbody><tr><td>危金矿</td><td>建设项目安全设施的<strong>设计人、设计单位</strong>应当对安全实施<strong>设计</strong>负责</td><td><strong>安全实施设计</strong>应当按照国家规定报<strong>有关部门审查，审查部门对审查人</strong>应当对审<strong>查结果负责</strong></td><td><strong>实施单位</strong>必须按照批准的施工，并对实施的<strong>工程质量</strong>负责</td><td>竣工使用前应当<strong>建设单位</strong>负责组织对安全设施进行验收，合格才能使用</td><td>安全监督职责部门应当对建设单位的验收和结果监督核查</td></tr></tbody></table><h4 id="_2-5危险物品、事故隐患、重大危险源的规定" tabindex="-1">2.5危险物品、事故隐患、重大危险源的规定 <a class="header-anchor" href="#_2-5危险物品、事故隐患、重大危险源的规定" aria-label="Permalink to &quot;2.5危险物品、事故隐患、重大危险源的规定&quot;">​</a></h4><p>要求：</p><ul><li>危险物品的标志 <blockquote><p>生产经营单位应当在有较大危险因素的生产经营场所和有关设施、设备上，设置明显的<strong>安全警示标志</strong> 。<br> ！针对<strong>危险+海特+矿特</strong>，由<strong>专业单位生产</strong>，取得<strong>安全使用证或安全标志</strong>，检测及机构负检测结果责。</p></blockquote></li><li>重大危险源的备案 <blockquote><p>建档：<strong>生产单位</strong>对重大危险源<strong>登记建档</strong>，定期检测、<strong>评估</strong>、监控，告知及紧急采取应急措施。 备案： 生产单位向（县级）有关<strong>部门备案</strong></p></blockquote></li></ul><p><em>单位建档，部门备案</em></p><ul><li>事故隐患 <blockquote><p>事前：生产单位建立<strong>安全风险分级管控</strong><br> 事中：落实生产安全事故隐患排查，及时发现并<strong>消除事故隐患</strong><br> 事后：事故隐患--<strong>从业人员通报</strong>，重大事故隐患--向生产监督部门和职工大会<strong>报告</strong>（双报告）</p></blockquote></li></ul><h4 id="_2-6员工宿舍与劳动防护用品" tabindex="-1">2.6员工宿舍与劳动防护用品 <a class="header-anchor" href="#_2-6员工宿舍与劳动防护用品" aria-label="Permalink to &quot;2.6员工宿舍与劳动防护用品&quot;">​</a></h4><p>员工宿舍：生产、存储、生活不得在一起 劳动防护用户：满足国标和行标，生产单位 危险作业现场： <strong>爆破、吊装、动火、临时用电</strong>（临吊火爆）及国家其他现场，安排<strong>专人</strong>进行<strong>现场安全管理</strong></p><h4 id="_2-7交叉作业、发包出租" tabindex="-1">2.7交叉作业、发包出租 <a class="header-anchor" href="#_2-7交叉作业、发包出租" aria-label="Permalink to &quot;2.7交叉作业、发包出租&quot;">​</a></h4><ul><li><p>交叉双方：<br> ① 应当<strong>签订安全生产管理协议，明确各自的职责</strong><br> ② 并<strong>指定专职</strong>进行安全检查</p></li><li><p>发包出租：<br> ① <strong>不得</strong>出租发包给<strong>不具备</strong>相关条件的<br> ② 责任：<strong>签协议</strong>或<strong>合同约定</strong><br> ③ 协调：<strong>生产单位</strong>对承租方统一<strong>协调、管理</strong></p></li></ul><h3 id="_3-从业人员的安全生产权利义务" tabindex="-1">3. 从业人员的安全生产权利义务 <a class="header-anchor" href="#_3-从业人员的安全生产权利义务" aria-label="Permalink to &quot;3. 从业人员的安全生产权利义务&quot;">​</a></h3><h4 id="_3-1-从业人员安全生产权利" tabindex="-1">3.1 从业人员安全生产权利 <a class="header-anchor" href="#_3-1-从业人员安全生产权利" aria-label="Permalink to &quot;3.1 从业人员安全生产权利&quot;">​</a></h4><p>生产单位--从业人员：</p><ul><li>依法购买<strong>工伤保险</strong>，不得签到免除责任。</li><li>保险机构对单位赔偿，预防及提供安全事故</li><li>安全责任保险：鼓励（高危强制：未孕建金矿+渔业）</li><li>人员：提意见、批评、拒绝违章紧急--采取可能的措施--撤离</li></ul><h4 id="_3-2-从业人员安全生产义务" tabindex="-1">3.2 从业人员安全生产义务 <a class="header-anchor" href="#_3-2-从业人员安全生产义务" aria-label="Permalink to &quot;3.2 从业人员安全生产义务&quot;">​</a></h4><ul><li>义务： 发现隐患上报领导，遵章守法，佩戴劳保</li></ul><h3 id="_4-安全生产的监督管理" tabindex="-1">4. 安全生产的监督管理 <a class="header-anchor" href="#_4-安全生产的监督管理" aria-label="Permalink to &quot;4. 安全生产的监督管理&quot;">​</a></h3><h4 id="_4-1-主管部门的监管职责" tabindex="-1">4.1 主管部门的监管职责 <a class="header-anchor" href="#_4-1-主管部门的监管职责" aria-label="Permalink to &quot;4.1 主管部门的监管职责&quot;">​</a></h4><p>主管部门职责：审查批准，验收&lt;证&gt; 权限：</p><ul><li>不批准：不合法、不合标准</li><li>取缔：未批准，擅自活动--举报，应<strong>取缔</strong></li><li>撤销：已批准，不具备，应<strong>撤销</strong></li><li>不收费，不指定</li></ul><h4 id="_4-2-监督检查" tabindex="-1">4.2 监督检查 <a class="header-anchor" href="#_4-2-监督检查" aria-label="Permalink to &quot;4.2 监督检查&quot;">​</a></h4><p>监察人员：（工贸企业+危+爆竹）</p><ul><li>现场检查：涉密可看，要保密</li><li>现场处置：违法行为--纠正，限期改正；个人200以下，单位3000元以下</li><li>紧急处理：事故--立即排除，<strong>重大事故隐患--无法保安全</strong>的--<strong>撤离</strong>--<strong>暂停</strong>生产--排出后经<strong>审查同意</strong>恢复</li><li>查封扣押：不符合</li></ul><p>安全检查要求：</p><ul><li>不影响生产</li><li>出示<strong>行政执法</strong>证件，&gt;=2人</li><li><strong>*书面记录</strong>，<strong>检查人与被检查负责人</strong>签字--被检查拒绝应<strong>记录在案</strong></li><li>联合检查，互通情况</li></ul><h4 id="_4-3-停电、惩戒" tabindex="-1">4.3 停电、惩戒 <a class="header-anchor" href="#_4-3-停电、惩戒" aria-label="Permalink to &quot;4.3 停电、惩戒&quot;">​</a></h4><ul><li>重大安全隐患，要求停业</li><li><strong>拒不执行</strong>企业，有<strong>现实危险</strong>，经<strong>部门负责人批准</strong>可通知停电 <blockquote><p>① 通过书面形式<br> ② <strong>提前24小时</strong></p></blockquote></li></ul><p>联合惩戒：<br><strong>有关部门和机构</strong>，对<strong>失信</strong>企业及从业人，采取加大<strong>检查频次、暂停审批、上调</strong>有关保费，或从业人<strong>禁入</strong>，向<strong>社会公示</strong></p><h4 id="_4-4-举报、公益诉讼" tabindex="-1">4.4 举报、公益诉讼 <a class="header-anchor" href="#_4-4-举报、公益诉讼" aria-label="Permalink to &quot;4.4 举报、公益诉讼&quot;">​</a></h4><p>举报：</p><ul><li><strong>任何单位和个人</strong>都可以举报</li><li>涉及<strong>死亡</strong>，由<strong>县级以上人民政府</strong>组织核查处理</li></ul><p>公益诉讼：<br> 造成<strong>重大事故隐患或导致重大事故</strong>，致<strong>国家利益或社会公共利益</strong>侵害，<strong>*人民检察院</strong>提起</p><h3 id="_5-生产安全事故的应急救援与调查处理" tabindex="-1">5.生产安全事故的应急救援与调查处理 <a class="header-anchor" href="#_5-生产安全事故的应急救援与调查处理" aria-label="Permalink to &quot;5.生产安全事故的应急救援与调查处理&quot;">​</a></h3><h4 id="_5-1-政府应急救援的职责" tabindex="-1">5.1 政府应急救援的职责 <a class="header-anchor" href="#_5-1-政府应急救援的职责" aria-label="Permalink to &quot;5.1 政府应急救援的职责&quot;">​</a></h4><p>国家：</p><ul><li>统一协调</li><li>鼓励建设<br> 县级以上人民政府：本行政区域 乡政人民政府：协助</li></ul><h4 id="_5-2-单位应急救援组织" tabindex="-1">5.2 单位应急救援组织 <a class="header-anchor" href="#_5-2-单位应急救援组织" aria-label="Permalink to &quot;5.2 单位应急救援组织&quot;">​</a></h4><ul><li>应急预案：<strong>生产经营单位</strong>，应当制定<strong>应急救援预案</strong>，与当地县级人民政府预案<strong>相衔接</strong>，并<strong>定期组织演练</strong></li><li>应急器材：<strong>未见到金矿</strong>应当配备及定期保养维护</li><li>应急组织：①<strong>未见到金矿</strong>+②生产规模较小（指定兼职应急救援人）</li></ul><h4 id="_5-3-事故报告" tabindex="-1">5.3 事故报告 <a class="header-anchor" href="#_5-3-事故报告" aria-label="Permalink to &quot;5.3 事故报告&quot;">​</a></h4><p>民报民：立即（领导）<br> 民报官：1小时（事故当地县级以上人民政府应急部门和有关富有安全职责部门）<br> 官报官：2小时</p><p>事故救援：</p><ul><li>政府、应急--立即赶现场，组织抢救</li><li>单位、个人--支持配合，提供便利</li></ul><h3 id="_6-法律责任-4分" tabindex="-1">6.法律责任 4分 <a class="header-anchor" href="#_6-法律责任-4分" aria-label="Permalink to &quot;6.法律责任 4分&quot;">​</a></h3><h4 id="_6-1-技术服务机构的法律责任" tabindex="-1">6.1 技术服务机构的法律责任 ** <a class="header-anchor" href="#_6-1-技术服务机构的法律责任" aria-label="Permalink to &quot;6.1 技术服务机构的法律责任 \\*\\*&quot;">​</a></h4><ul><li>失实报告：停业、3~10W罚款</li><li>租借、挂靠、虚假报告： <blockquote><ol><li>① <strong>没收</strong>违法所得 ② 罚款：违法所得在<strong>10W以上，罚2~5倍</strong>；<strong>不足10W，罚10~20W</strong> ③ 连带责任</li><li>直接<strong>责任主管和其他直接责任人，罚5~10W</strong></li><li>机构、人员<strong>吊销</strong>资质（格），<strong>5年内</strong>不从事，<strong>情节严重</strong>终身不得从事</li></ol></blockquote></li></ul><h4 id="_6-2-人员的法律责任" tabindex="-1">6.2 人员的法律责任 *** <a class="header-anchor" href="#_6-2-人员的法律责任" aria-label="Permalink to &quot;6.2 人员的法律责任 \\*\\*\\*&quot;">​</a></h4><p>安全费用投入不够：</p><blockquote><p>未发生事故：限期改正，<strong>逾期</strong>停业停产整顿<br> 发生事故：个人经营投资人罚<strong>2~20W</strong> 上一年收入：40%（一般）、60%（较大）、80%（重大）、100%（特别重大）<br> 刑事责任：自刑罚执行起<strong>5年</strong>内不得担任<strong>任何</strong>生产单位的主要负责人，对于<strong>重大、特别重大</strong>的<strong>终生</strong>的不得本行业主要责任人</p></blockquote><blockquote><p>《安全事故规定》负责人罚款：2W~5W（一般）5W~10W(较大)10W~15W(重大)15W~20W(特别重大)</p></blockquote><p>主要负责人没有参与或擅离职守、逃匿（安全生产法）：</p><ol><li>降级、撤职</li><li>**60%~100%**的上一年收入罚款</li><li><strong>逃匿</strong>的处15日以下的<strong>拘留</strong></li><li>构成犯罪的，追究刑事责任</li><li>隐瞒不报、谎报、迟报按以上处罚</li></ol><blockquote><p>安全生产条例：轻（迟、漏报、擅离职守）40%~80%，重（谎、瞒、伪造、转移、隐匿、拒绝、逃匿）：个人60%~100%，且单位100W~500W</p></blockquote><p>其他责任人和安全责任人（安全法）：<br> 生产管理人员未履行职责：暂停或吊销有关资格，并处**20%~50%**上一年收入的罚款</p><blockquote><p>安全事故规定：20%~30%（一般）30%~40%(较大)40%~50%(重大)</p></blockquote><h4 id="_6-3-单位的法律责任" tabindex="-1">6.3 单位的法律责任 ** <a class="header-anchor" href="#_6-3-单位的法律责任" aria-label="Permalink to &quot;6.3 单位的法律责任 \\*\\*&quot;">​</a></h4><ul><li>生产单位未发生事故：</li></ul><table tabindex="0"><thead><tr><th></th><th>单位</th><th>初次(万元)</th><th>逾期(万元)</th><th>责任人</th><th>初次(万元)</th><th>逾期（万元）</th></tr></thead><tbody><tr><td>设备设施</td><td>单位</td><td>5以下</td><td>5～20</td><td>责任人</td><td></td><td>1～2</td></tr><tr><td>管理</td><td>单位</td><td>10以下</td><td>10～20</td><td>责任人</td><td></td><td>2～5</td></tr><tr><td>审核</td><td>单位</td><td>10～50</td><td>50～100</td><td>责任人</td><td>2～5</td><td>5～10</td></tr></tbody></table><ul><li>生产单位发生事故单位罚款：30W~100W~200W~1000W~2000W(<strong>1212</strong>)</li><li>条例罚款：10W~20W~50W~200W~500W(<strong>2525</strong>)</li></ul><p>事故判断表格：</p><table tabindex="0"><thead><tr><th style="text-align:center;">判定指标</th><th style="text-align:center;">一般事故</th><th style="text-align:center;">较大事故</th><th style="text-align:center;">重大事故</th><th style="text-align:center;">特别重大事故</th></tr></thead><tbody><tr><td style="text-align:center;">死亡人数</td><td style="text-align:center;">&lt;3人</td><td style="text-align:center;">3~9人</td><td style="text-align:center;">10~29人</td><td style="text-align:center;">≥30人</td></tr><tr><td style="text-align:center;">重伤人数</td><td style="text-align:center;">&lt;10人</td><td style="text-align:center;">10~49人</td><td style="text-align:center;">50~99人</td><td style="text-align:center;">≥100人</td></tr><tr><td style="text-align:center;">直接经济损失</td><td style="text-align:center;">&lt;1000万元</td><td style="text-align:center;">1000万~5000万元</td><td style="text-align:center;">5000万~1亿元</td><td style="text-align:center;">≥1亿元</td></tr></tbody></table><h2 id="第四章-安全生产单行法律" tabindex="-1">第四章 安全生产单行法律 <a class="header-anchor" href="#第四章-安全生产单行法律" aria-label="Permalink to &quot;第四章 安全生产单行法律&quot;">​</a></h2><h3 id="_1-消防法" tabindex="-1">1. 消防法 * <a class="header-anchor" href="#_1-消防法" aria-label="Permalink to &quot;1. 消防法 \\*&quot;">​</a></h3><h4 id="_1-1-基本规定" tabindex="-1">1.1 基本规定 <a class="header-anchor" href="#_1-1-基本规定" aria-label="Permalink to &quot;1.1 基本规定&quot;">​</a></h4><p>消防验收：住建部--建设部门，其他--备案等抽查 消防检查：</p><ul><li>告知：投用前在<strong>建设单位或使用单位</strong>向当地县级人民政府<strong>消防机构</strong>申请<strong>消防安全检查</strong></li><li>不告知：提取申请<strong>10个工作日内</strong>进行检查</li></ul><p>一般单位的消防安全职责：<strong>每年至少一次</strong>全面检测</p><p>消防安全重点单位的安全职责：</p><ul><li>县级以上地方政府<strong>消防救援机构</strong>对有可能发生重大单位，并由<strong>应急管理部门</strong>报<strong>本级人民政府备案</strong>。</li><li>履行：人定巡档--①确<strong>定</strong>安全管理<strong>人</strong>②<strong>建</strong>立消防档案③<strong>每日防火巡查</strong>④<strong>定期</strong>组织演练</li></ul><h4 id="_1-2-消防组织的规定" tabindex="-1">1.2 消防组织的规定 <a class="header-anchor" href="#_1-2-消防组织的规定" aria-label="Permalink to &quot;1.2 消防组织的规定&quot;">​</a></h4><p>消防队伍的建立：</p><ul><li>政府： 县级以上--应当建立，乡镇--根据当地经济发展或需要</li><li>单位： 一般--根据需要，高危--应当建立</li></ul><p>应建立专职消防队的单位：</p><ul><li>鹤岗非法（核电飞港）+ 危险&lt;大型、主要&gt;</li><li>可燃+重要</li></ul><h4 id="_1-3-灭火救援的规定" tabindex="-1">1.3 灭火救援的规定 <a class="header-anchor" href="#_1-3-灭火救援的规定" aria-label="Permalink to &quot;1.3 灭火救援的规定&quot;">​</a></h4><ul><li>县级政府：组织有关部门制定预案</li><li>火灾现场总指挥：停水电燃气、交通管制、拆除建筑、调动有关单位</li><li>单位：立即组织扑救</li><li>个人：立即报警、无偿提供<strong>报警</strong>便利 、耗损<strong>政府</strong>补</li></ul><h3 id="_2-交通安全法" tabindex="-1">2. 交通安全法 <a class="header-anchor" href="#_2-交通安全法" aria-label="Permalink to &quot;2. 交通安全法&quot;">​</a></h3><ul><li><strong>道路主管部门+公安机关交通管理部门</strong></li><li>高速拦车：只有公安执行公务</li></ul><h3 id="_3-特种设备安全法" tabindex="-1">3. 特种设备安全法 <a class="header-anchor" href="#_3-特种设备安全法" aria-label="Permalink to &quot;3. 特种设备安全法&quot;">​</a></h3><h4 id="_3-1-特种设备的生产" tabindex="-1">3.1 特种设备的生产 <a class="header-anchor" href="#_3-1-特种设备的生产" aria-label="Permalink to &quot;3.1 特种设备的生产&quot;">​</a></h4><ul><li>特种设备的总则 <blockquote><p>范围：游客叉中电压力锅</p></blockquote></li><li>特种设备生产单位 <blockquote><p>设计文件要鉴定--游客杨锅瓶；实验【需要】--新产品、新材料、新部件</p></blockquote></li><li>特种设备的安装、改造、修理 <blockquote><p>施工前：施工单位向市级部门书面报告<br> 验收后：30日内向使用单位移交资料 电梯的安全性能--电梯制造单位负责</p></blockquote></li></ul><h4 id="_3-2-特种设备的经营" tabindex="-1">3.2 特种设备的经营 <a class="header-anchor" href="#_3-2-特种设备的经营" aria-label="Permalink to &quot;3.2 特种设备的经营&quot;">​</a></h4><p>销售单位：检查验收和销售记录制度<br> 出租单位：对使用管理和维护保养负责</p><h4 id="_3-3-特种设备的使用" tabindex="-1">3.3 特种设备的使用 <a class="header-anchor" href="#_3-3-特种设备的使用" aria-label="Permalink to &quot;3.3 特种设备的使用&quot;">​</a></h4><p>设备管理：</p><ul><li><strong>*投入使用前</strong>或<strong>投入使用后三十日内</strong>向市级办理登记，取得<strong>使用登记证书</strong>，<strong>登记标志</strong>应至于该设备<strong>显著位置</strong></li><li>机构或专职：电梯、客运索道、大型游乐设施</li></ul><p>维护保养定期检验：</p><ul><li>使用单位：（每月至少一次） 、定期自行检查、故障\\异常--全面检查</li><li>出现问题：管理人员立即处理、作业人员报告</li><li>定期检验：有效期满前1个月提</li><li>客索、大型游乐设施：每日试运行、例行检查</li></ul><p>电梯：</p><ul><li>维护保养：制造单位、许可的单位（对其维护保养的电梯安全性能负责）</li><li>每15日一次清洁、润滑、调整和检查</li><li>跟踪调查了解：电梯制造到位</li><li>严重事故隐患：告知电梯使用单位</li></ul><h4 id="_3-4-特种设备的改造与报废" tabindex="-1">3.4 特种设备的改造与报废 <a class="header-anchor" href="#_3-4-特种设备的改造与报废" aria-label="Permalink to &quot;3.4 特种设备的改造与报废&quot;">​</a></h4><p>报废：原登记部门+注销<br> 继续使用： <strong>检验或安全评估</strong>+办理<strong>使用登记证书变更</strong></p><h4 id="_3-5-特种设备的检验、检测" tabindex="-1">3.5 特种设备的检验、检测 <a class="header-anchor" href="#_3-5-特种设备的检验、检测" aria-label="Permalink to &quot;3.5 特种设备的检验、检测&quot;">​</a></h4><p>机构+人员：严重事故隐患--告知单位、部门，不得推荐、监制<br> 人员：不得多机构执业</p><h4 id="_3-6-特种设备的监督管理" tabindex="-1">3.6 特种设备的监督管理 <a class="header-anchor" href="#_3-6-特种设备的监督管理" aria-label="Permalink to &quot;3.6 特种设备的监督管理&quot;">​</a></h4><ul><li>职权：现场检查、查阅 复印资料；严重隐患、报废--查封</li><li>2人及以上执法+行政执法证件</li><li>不得 要求单位重复取得许可证</li><li>检查情况：书面记录+检查人员、负责人签字</li></ul><h3 id="_4-建筑法" tabindex="-1">4. 建筑法 <a class="header-anchor" href="#_4-建筑法" aria-label="Permalink to &quot;4. 建筑法&quot;">​</a></h3><h4 id="_4-1-建筑工程发包与承包" tabindex="-1">4.1 建筑工程发包与承包 <a class="header-anchor" href="#_4-1-建筑工程发包与承包" aria-label="Permalink to &quot;4.1 建筑工程发包与承包&quot;">​</a></h4><ul><li>发包：有资质</li><li>承包： <ul><li>资质： 资质等级许可范围内</li><li>分包： 有约依约，无约同意</li><li>责任承担： 基于合同关系</li></ul></li></ul><h4 id="_4-2-建筑安全生产管理" tabindex="-1">4.2 建筑安全生产管理 <a class="header-anchor" href="#_4-2-建筑安全生产管理" aria-label="Permalink to &quot;4.2 建筑安全生产管理&quot;">​</a></h4><ul><li>施工许可证/开工报告：<strong>3个月内</strong>开工，不能开工<strong>申请延期</strong>--两次，每次不超过三个月</li><li>终止施工：终止<strong>一个月内</strong>发证机关<strong>报告</strong>、满一年<strong>核验</strong></li><li>重新办理：按期超6月未开工</li></ul><h4 id="_4-3-建筑工程质量管理" tabindex="-1">4.3 建筑工程质量管理 <a class="header-anchor" href="#_4-3-建筑工程质量管理" aria-label="Permalink to &quot;4.3 建筑工程质量管理&quot;">​</a></h4><ul><li>施工： 对施工质量负责，有意见提意见，不能修改设计</li><li>设计： 对设计负责，除有特殊要求，<strong>不得指定</strong>供应商</li></ul><h3 id="_5-危险化学品安全法-5-6分" tabindex="-1">5. 危险化学品安全法 （5~6分） <a class="header-anchor" href="#_5-危险化学品安全法-5-6分" aria-label="Permalink to &quot;5. 危险化学品安全法 （5~6分）&quot;">​</a></h3><h4 id="_5-1-基本规定" tabindex="-1">5.1 基本规定 <a class="header-anchor" href="#_5-1-基本规定" aria-label="Permalink to &quot;5.1 基本规定&quot;">​</a></h4><h5 id="_5-1-1-危险化学品单位及危险化学品的范围" tabindex="-1">5.1.1 危险化学品单位及危险化学品的范围 <a class="header-anchor" href="#_5-1-1-危险化学品单位及危险化学品的范围" aria-label="Permalink to &quot;5.1.1 危险化学品单位及危险化学品的范围&quot;">​</a></h5><ul><li>适用：具有毒害、腐蚀、爆炸、燃烧、助燃等性质，对人体、设施、环境有危害的剧毒及其他化学品。</li><li>不适用：<strong>民用爆炸物、烟花爆竹、放射性、核能物质、国防科研生产的危险化学品</strong><blockquote><p>危险化学品容器属于<strong>特种设备</strong></p></blockquote></li></ul><h5 id="_5-1-2-危险化学品监督管理部门的职责" tabindex="-1">5.1.2 危险化学品监督管理部门的职责 <a class="header-anchor" href="#_5-1-2-危险化学品监督管理部门的职责" aria-label="Permalink to &quot;5.1.2 危险化学品监督管理部门的职责&quot;">​</a></h5><ul><li>应急管理部： <strong>监督管理、安全条件审查、发证（生产、使用、经营）、登记</strong></li><li>公安部： 运输通行证、购买许可证</li><li>交通部： <strong>运输许可</strong>或备案及运输工具的安全监督管理，运输人员<strong>资格认定</strong></li><li>市场部： <strong>签发营业执照</strong>，工业产品生产许可证</li><li>卫生部： 毒性检测、事故救援工作</li></ul><h5 id="_5-1-3-危险化学品安全监督管理部门的监督检查权" tabindex="-1">5.1.3 危险化学品安全监督管理部门的监督检查权 <a class="header-anchor" href="#_5-1-3-危险化学品安全监督管理部门的监督检查权" aria-label="Permalink to &quot;5.1.3 危险化学品安全监督管理部门的监督检查权&quot;">​</a></h5><ul><li><strong>重大危险</strong>开展<strong>在线巡查抽检</strong></li><li>有隐患，需消除</li><li>不符合规定，停止使用</li><li>部门负责人<strong>批准</strong>，<strong>查封</strong>违法生产、储存、使用、经营的场所，<strong>扣押</strong>违法生产-+运</li><li>违法行为，纠正或责令限期改正</li><li>两人执法，出示执法证件</li></ul><h4 id="_5-2-规划布局" tabindex="-1">5.2 规划布局 <a class="header-anchor" href="#_5-2-规划布局" aria-label="Permalink to &quot;5.2 规划布局&quot;">​</a></h4><ul><li>危险化学品生产储存的分级规划管理化工</li><li>园区的设立、监管与风险评估： <ul><li>评估：省级认定公布</li><li>化工园区：至少<strong>每三年</strong>开展一次整体性安全风险评估、发生变化应该<strong>重新</strong>开展风险评估，并修应急预案</li><li>不符合安全距离：<strong>市级人民应急部门</strong>在期限内进行<strong>整改</strong>；</li><li>需要转产、停、搬、关的： <strong>由本级人民政府</strong>决定并组织实施</li></ul></li></ul><h4 id="_5-3-生产和储存安全" tabindex="-1">5.3 生产和储存安全 <a class="header-anchor" href="#_5-3-生产和储存安全" aria-label="Permalink to &quot;5.3 生产和储存安全&quot;">​</a></h4><h5 id="_5-3-1-危险化学品建设项目安全条件审查" tabindex="-1">5.3.1 危险化学品建设项目安全条件审查 <a class="header-anchor" href="#_5-3-1-危险化学品建设项目安全条件审查" aria-label="Permalink to &quot;5.3.1 危险化学品建设项目安全条件审查&quot;">​</a></h5><ul><li>危险化学品的建设项目： <ul><li>审查：应当由<strong>应急管理部门</strong>安全条件审查</li><li>安全评价：建设单位有国家资质条件的机构对项目进行<strong>安全评价</strong></li><li>安全评价情况：并将安全评价报所在地区**市级以上的人民政府***应急部门</li></ul></li><li>危险港口建设：港口行政管理部门</li></ul><h5 id="_5-3-2-危险化学品建设项目安全设施设计及审查" tabindex="-1">5.3.2 危险化学品建设项目安全设施设计及审查 <a class="header-anchor" href="#_5-3-2-危险化学品建设项目安全设施设计及审查" aria-label="Permalink to &quot;5.3.2 危险化学品建设项目安全设施设计及审查&quot;">​</a></h5><p>设计（市）：</p><ul><li>三同时： 同时设计、同时施工、同时投入生产和使用。安全设施投资纳入项目概算</li><li>安全设施设计：设计人、设计单位需要对安全设施设计负责</li><li>安全设施设计审查： <strong>市级以上人民政府应急管理部门</strong>，港口找港口行政管理部门</li><li>施工： 施工对施工安全、质量负责</li><li>验收： <strong>建设单位</strong>对安全设施验收。部门还需核查</li></ul><h5 id="_5-3-3-危险化学品生产" tabindex="-1">5.3.3 危险化学品生产 <a class="header-anchor" href="#_5-3-3-危险化学品生产" aria-label="Permalink to &quot;5.3.3 危险化学品生产&quot;">​</a></h5><p>生产（县）：</p><ul><li>生产企业：生成前取得<strong>危险化学品安全生产许可证</strong></li><li>列入国家危险产品目录的危险的企业：还应该取得<strong>工业产品生产许可证</strong>，试生产的危品需有资质的机构<strong>检验合格</strong>才可销售</li><li>发证情况需要<strong>向社会公开</strong></li></ul><h5 id="_5-3-4-储存安全管理" tabindex="-1">5.3.4 储存安全管理 <a class="header-anchor" href="#_5-3-4-储存安全管理" aria-label="Permalink to &quot;5.3.4 储存安全管理&quot;">​</a></h5><p>储存（县）：</p><ul><li>一般危险化学品：专人专库存储，专人负责管理</li><li><strong>剧毒</strong>化学品及<strong>储存数量构成重大危险源的其他</strong>危险化学品：应当专用存储场所内<strong>单独存放</strong>，还需<strong>双人收发、双人保管</strong>制度，并收发记录不得少于<strong>三年</strong></li><li>定期检测</li><li>标签及说明书：物与标签相符，并满足<strong>国家标准</strong>。新的危险特性应<strong>立即公告，及时修订</strong>标签及说明书</li><li>重复使用必检：发现安全隐患<strong>及时维修或更换</strong>，检出做出记录并保存期限<strong>不少于三年</strong></li><li>备案：存储信息需要备案--<strong>县级人民政府应急管理部门、消防救援机构和公安机关</strong>备案。港口对应港口管理部门、消防及公安机关备案</li></ul><p>生产、存储安全管理（县）：</p><ul><li>安全评价：企业应委托资质的机构对本企业安全生产条件,<strong>每三年</strong>进行安全评价,并向社会公开</li><li>备案：生产存储的企业应将安全评价报告以及整改报<strong>所在地县级人民政府应急管理部门</strong>备案</li></ul><p>特殊危险化学品的安全管理：</p><ul><li>特殊：剧毒、易制爆（安保卫<strong>机构</strong>、配备<strong>专职</strong>治安保卫人员）</li><li>丢失被盗：防止，发现被盗向<strong>当地公安机关报告</strong></li><li>转让：向所在县级人民政府<strong>公安机关</strong>备案</li></ul><h4 id="_5-4-使用安全" tabindex="-1">5.4 使用安全 ** <a class="header-anchor" href="#_5-4-使用安全" aria-label="Permalink to &quot;5.4 使用安全 \\*\\*&quot;">​</a></h4><p>危险化学品安全使用许可证:</p><ul><li>使<strong>用</strong>危险化学品从事生产并且使用量达到<strong>规定数量</strong>的<strong>化工企业</strong>（生产企业除外）-- 用+量+化工 <blockquote><p><strong>用+量+化工</strong> 安全条件：</p></blockquote></li><li>专业技术人员，从业人员经<strong>考核合格</strong></li><li>有安全管理<strong>机构和专职</strong>安全管理人员</li><li>应急预案</li><li>依法进行安全评价 <blockquote><p><strong>从业考核合格+机构、专职+应急预案+安全评估</strong></p></blockquote></li></ul><p>申办程序：所在地<strong>设去的市级</strong>人民政府<strong>应急管理部门</strong>提出申请</p><blockquote><p><strong>市应急管理部门</strong></p></blockquote><h4 id="_5-5-经营安全" tabindex="-1">5.5 经营安全 <a class="header-anchor" href="#_5-5-经营安全" aria-label="Permalink to &quot;5.5 经营安全&quot;">​</a></h4><h5 id="_5-5-1-经营许可证" tabindex="-1">5.5.1 经营许可证 <a class="header-anchor" href="#_5-5-1-经营许可证" aria-label="Permalink to &quot;5.5.1 经营许可证&quot;">​</a></h5><p>范围：</p><ul><li>经营许可：许可经营</li><li>特殊： <ul><li><strong>生产企业</strong>在<strong>其厂区范围内销售本企业上产</strong>的危险化学品，<strong>不需要</strong>获取经营许可</li><li>港口经营许可证的在港口内从事化学危险品仓储经营的，不需要</li></ul></li></ul><p>申办程序：</p><ul><li>市应急管理：① <strong>剧毒、易制爆</strong>危险化学品；② <strong>有存储设施且书数量构成重大危险源的</strong></li><li>县应急管理：从事其他化学经营的企业</li><li>向社会公开</li></ul><p>登记：向市场管理部门</p><h5 id="_5-5-2-剧毒化学品购买许可证" tabindex="-1">5.5.2 剧毒化学品购买许可证 <a class="header-anchor" href="#_5-5-2-剧毒化学品购买许可证" aria-label="Permalink to &quot;5.5.2 剧毒化学品购买许可证&quot;">​</a></h5><ul><li>企业购买许可证：<strong>县级人民政府公安机关</strong>申请取得</li><li>提供材料： <ul><li>印业执照或登记证书的复印件</li><li>品类品种、数量的说明</li><li>用途的说明</li><li><strong>经办人的身份证明</strong></li></ul></li></ul><h5 id="_5-5-3-购买剧毒化学品、易制爆危险化学品的安全规定" tabindex="-1">5.5.3 购买剧毒化学品、易制爆危险化学品的安全规定 <a class="header-anchor" href="#_5-5-3-购买剧毒化学品、易制爆危险化学品的安全规定" aria-label="Permalink to &quot;5.5.3 购买剧毒化学品、易制爆危险化学品的安全规定&quot;">​</a></h5><p>经营安全：</p><ul><li>依法取得生产、使用、经营证的企业，凭证购买</li><li>民爆、烟花爆竹、武器装备科研企业凭证购买易制爆</li><li>个人不得购买（属于剧毒化学品的<strong>农药除外</strong>）</li></ul><h5 id="_5-5-4-销售剧毒化学品、易制爆危险化学品的安全规定" tabindex="-1">5.5.4 销售剧毒化学品、易制爆危险化学品的安全规定 <a class="header-anchor" href="#_5-5-4-销售剧毒化学品、易制爆危险化学品的安全规定" aria-label="Permalink to &quot;5.5.4 销售剧毒化学品、易制爆危险化学品的安全规定&quot;">​</a></h5><ul><li>禁止向个人销售剧毒化学品（剧毒化学品的<strong>农药除外</strong>）；和易制爆（<strong>生活品除外</strong>）</li><li>经营的记录保存期限不少于<strong>三年</strong></li><li>销售<strong>三日</strong>内向所在地<strong>县级公安机</strong>关备案</li></ul><h4 id="_5-6-运输安全" tabindex="-1">5.6 运输安全 <a class="header-anchor" href="#_5-6-运输安全" aria-label="Permalink to &quot;5.6 运输安全&quot;">​</a></h4><h5 id="_5-6-1-道路、水路运输的资质和资格" tabindex="-1">5.6.1 道路、水路运输的资质和资格 <a class="header-anchor" href="#_5-6-1-道路、水路运输的资质和资格" aria-label="Permalink to &quot;5.6.1 道路、水路运输的资质和资格&quot;">​</a></h5><p>运输许可：向<strong>市场监督管理部门</strong>办理<strong>登记</strong>手续，取得<strong>运输许可</strong>或<strong>办理备案</strong>手续 通行证：<strong>托运人</strong>向运输<strong>始发地</strong>或<strong>目的地县级公安机关</strong>申请 人员资格： ① 配备<strong>专职</strong>安全管理人员 ② 相应人员（运、押、装、申、检）应当经<strong>交通运输主管部门考核</strong>合格，取得从业资格</p><h5 id="_5-6-2-道路运输安全管理" tabindex="-1">5.6.2 道路运输安全管理 <a class="header-anchor" href="#_5-6-2-道路运输安全管理" aria-label="Permalink to &quot;5.6.2 道路运输安全管理&quot;">​</a></h5><ul><li>道路运输危险化学品需要配备<strong>押运人员</strong></li><li>运输中通较长时间停车需报备条件：剧毒、易制爆<strong>当地公安机关</strong>报告</li></ul><h5 id="_5-6-3-水路运输安全管理" tabindex="-1">5.6.3 水路运输安全管理 <a class="header-anchor" href="#_5-6-3-水路运输安全管理" aria-label="Permalink to &quot;5.6.3 水路运输安全管理&quot;">​</a></h5><ul><li>禁止在封闭内河运输<strong>剧毒</strong>化学品</li><li>上报： <ul><li>危险化学品船舶<strong>进出内河港口</strong>应向<strong>海事管理机构</strong>报告（海）</li><li>内河港口内装卸作业<strong>报告港口行政管理部门</strong>（内河）</li></ul></li></ul><h4 id="_5-7-危险化学品登记与事故应急救援" tabindex="-1">5.7 危险化学品登记与事故应急救援 <a class="header-anchor" href="#_5-7-危险化学品登记与事故应急救援" aria-label="Permalink to &quot;5.7 危险化学品登记与事故应急救援&quot;">​</a></h4><h5 id="_5-7-1-危险化学品登记管理" tabindex="-1">5.7.1 危险化学品登记管理 <a class="header-anchor" href="#_5-7-1-危险化学品登记管理" aria-label="Permalink to &quot;5.7.1 危险化学品登记管理&quot;">​</a></h5><ul><li>登记： <strong>生产企业、进口企业</strong>登记机构登记</li><li>登记内容： <ul><li>分类和标签信息</li><li>物理、化学性质</li><li>用途</li><li>危险特性</li><li>储、使、运的安全要求</li><li>出现危情应急处理措施</li></ul></li></ul><h5 id="_5-7-2-危险化学品事故应急救援" tabindex="-1">5.7.2 危险化学品事故应急救援 <a class="header-anchor" href="#_5-7-2-危险化学品事故应急救援" aria-label="Permalink to &quot;5.7.2 危险化学品事故应急救援&quot;">​</a></h5><p>政府：根据<strong>实际需要</strong>依托条件可以联合企业建立 单位：依法建立<strong>专职</strong>或<strong>兼职</strong>应急救援队伍；<strong>规模小</strong>可以不建立 应急预案备案：<strong>县级及以上的应急管理部门</strong>备案，并向社会公布</p><h2 id="第五章-安全生产相关法律" tabindex="-1">第五章 安全生产相关法律 <a class="header-anchor" href="#第五章-安全生产相关法律" aria-label="Permalink to &quot;第五章 安全生产相关法律&quot;">​</a></h2><h3 id="_1-民法典" tabindex="-1">1 民法典 <a class="header-anchor" href="#_1-民法典" aria-label="Permalink to &quot;1 民法典&quot;">​</a></h3><h4 id="_1-1-侵权责任与损害赔偿" tabindex="-1">1.1 侵权责任与损害赔偿 <a class="header-anchor" href="#_1-1-侵权责任与损害赔偿" aria-label="Permalink to &quot;1.1 侵权责任与损害赔偿&quot;">​</a></h4><ul><li>侵权：谁有错，谁担责，可追偿</li><li>损害赔偿：同一侵权行为，同命同价</li></ul><h4 id="_1-2-与安全有关的规定" tabindex="-1">1.2 与安全有关的规定 <a class="header-anchor" href="#_1-2-与安全有关的规定" aria-label="Permalink to &quot;1.2 与安全有关的规定&quot;">​</a></h4><ul><li>用人者责任：用人单位担责</li><li>劳务派遣： 用工单位担责</li><li>个人劳务： 接受方担责，可追偿</li></ul><h3 id="_2-刑法-3分左右" tabindex="-1">2 刑法 ** （3分左右） <a class="header-anchor" href="#_2-刑法-3分左右" aria-label="Permalink to &quot;2 刑法 \\*\\* （3分左右）&quot;">​</a></h3><h4 id="_2-1-判罚罪名" tabindex="-1">2.1 判罚罪名 <a class="header-anchor" href="#_2-1-判罚罪名" aria-label="Permalink to &quot;2.1 判罚罪名&quot;">​</a></h4><ul><li><p>重大责任事故罪、重大劳动安全事故罪：</p><ul><li>重大责任事故罪--<strong>违反</strong>...安全管理的规定 ***</li><li>重大劳动<strong>安全</strong>事故罪 -- 安全生产设施、安全生产条件</li><li>工程重大安全罪：降低工程质量(重大：5年下，特别严重：5-10年，罚金，其他都没有罚金)</li></ul></li><li><p>强令、组织他人违章冒险作业罪：-- <strong>强令、违章冒险</strong> ***</p></li><li><p>不报、谎报安全事故罪、危险作业罪：</p><ul><li>不报、谎报安全事故罪：<strong>不报、谎报</strong> ***</li><li>危险作业罪：违法规定 + <strong>现实危险</strong></li></ul></li><li><p>危险物品肇事罪、大型群众性活动重大安全事故罪：</p><ul><li>危险物品肇事罪：<strong>违反</strong>...物品的管理规定</li><li>大型群众性活动重大安全事故罪：违反<strong>大型活动</strong>+重大事故或严重后果，对<strong>直接责任的主管和其他直接责任</strong>人员</li></ul></li></ul><h4 id="_2-2-判罚期限" tabindex="-1">2.2 判罚期限 <a class="header-anchor" href="#_2-2-判罚期限" aria-label="Permalink to &quot;2.2 判罚期限&quot;">​</a></h4><ul><li>犯罪刑期：强令5，危险作业1，其他37</li><li>情节严重”的判定：1死3重伤100W直接损失（131）</li><li>情节特别严重”的判定： 3死10重伤500W直接损失（315）</li></ul><h3 id="_3-行政处罚法-1分" tabindex="-1">3 行政处罚法 1分 <a class="header-anchor" href="#_3-行政处罚法-1分" aria-label="Permalink to &quot;3 行政处罚法 1分&quot;">​</a></h3><ul><li>行政处罚的种类：官罚民</li><li>行政处罚权的设定： <ul><li>法律：限制人身自由</li><li>行政法规：除人身自由</li><li>地方部门：警告罚款</li></ul></li><li>行政处罚的管辖和适用： <ul><li>违法地+县级机关；</li><li>指定管辖：有争议，可协商</li><li>14以下，14~18岁</li></ul></li><li>行政处罚的决定 <ul><li>当面：个人200以下，单位3000元以下</li><li>听证：企业提出5日内，单位听证前7日；</li></ul></li><li>行政处罚的执行 <ul><li>当场100，特殊除外</li><li>15日内在指定银行或电子支付系统缴纳；逾期：每日3%加处罚款</li></ul></li></ul><h3 id="_4-行政强制法-1分" tabindex="-1">4 行政强制法 1分 <a class="header-anchor" href="#_4-行政强制法-1分" aria-label="Permalink to &quot;4 行政强制法 1分&quot;">​</a></h3><ul><li>行政强制的种类和设定 <ul><li>措施：静</li><li>执行：动</li></ul></li><li>行政强制措施实施程序 <ul><li>查封扣押：最多30日，延期最多30，行政机关承担保管费用</li></ul></li><li>行政机关强制执行程序 <ul><li>中止：暂停</li><li>终结：结束</li><li>金钱给付：超过三十日强制执行</li><li>申请人民法院强制执行：界时3个月内</li></ul></li></ul><h3 id="_5-劳动法-1分必考" tabindex="-1">5 劳动法 1分必考 <a class="header-anchor" href="#_5-劳动法-1分必考" aria-label="Permalink to &quot;5 劳动法 1分必考&quot;">​</a></h3><p>-女：</p><ul><li>一般：禁止四级体力劳动、矿山下井</li><li>经期:禁三级体力劳动、高处、低温、冷水作业</li><li>孕期:禁三级体力劳动、7个月以上不加班夜班</li><li>哺乳期:禁三级体力劳动、未满1周岁不加班夜班 16-18岁未成年:</li><li>矿山井下、第4级体力、有毒有害</li><li>定期健康检查</li></ul><h3 id="_6-劳动合同法-3分" tabindex="-1">6 劳动合同法 3分 <a class="header-anchor" href="#_6-劳动合同法-3分" aria-label="Permalink to &quot;6 劳动合同法 3分&quot;">​</a></h3><p>劳动合同的订立：用工之日起一个月内订立书面合同 劳动合同的建立：用工之日起 竞业：不超2年 解除：</p><h3 id="_7-突发事件应对法-2-3分" tabindex="-1">7 突发事件应对法 2-3分 <a class="header-anchor" href="#_7-突发事件应对法-2-3分" aria-label="Permalink to &quot;7 突发事件应对法 2-3分&quot;">​</a></h3><h4 id="_7-1-基本规定" tabindex="-1">7.1 基本规定 * <a class="header-anchor" href="#_7-1-基本规定" aria-label="Permalink to &quot;7.1 基本规定 \\*&quot;">​</a></h4><ul><li>突发事件的概念：自然、事故、公共卫生、社会安全</li><li>突发事件分级： 一般、较大、重大、特别重大</li><li>突发事件的应对：县级以上人民政府处理向上汇报</li><li>信息发布 ** <ul><li><strong>突发事件应急指挥机构</strong>可以发布决定、命令措施，与人民政府<strong>同等效力</strong></li><li>备案：发布命令及时<strong>本级人民代表大会常委委员会</strong>，结束后专项工作报告</li><li></li></ul></li></ul><h4 id="_7-2-预防与应急准备" tabindex="-1">7.2 预防与应急准备 * <a class="header-anchor" href="#_7-2-预防与应急准备" aria-label="Permalink to &quot;7.2 预防与应急准备 \\*&quot;">​</a></h4><p>应急物资储备保障：</p><ul><li><strong>市级</strong>以上和<strong>易发、多发的县级</strong>应当建立，县级根据需要</li></ul><h4 id="_7-3-监测与预警" tabindex="-1">7.3 监测与预警 ** <a class="header-anchor" href="#_7-3-监测与预警" aria-label="Permalink to &quot;7.3 监测与预警 \\*\\*&quot;">​</a></h4><p>信息收集与报告：</p><ul><li>建立： 国务院全国，县级以上地方人民政府本地</li><li>收集： 县级以上人民政府及有关部门、专业机构</li><li>报告： 县级建立专职或兼职信息报告员制度；个人、单位向所在地人民政府、有关部门、指定的专业机构</li></ul><p>预警级别：</p><ul><li>1-4级，对应--红橙黄绿</li></ul><p>预警后的措施：</p><ul><li>三四级： 预警、公示</li><li>一二级： 人员待命、调集物资、重点保卫、转移撤离、关闭场所</li></ul><h4 id="_7-4-应急处置与救援" tabindex="-1">7.4 应急处置与救援 ** <a class="header-anchor" href="#_7-4-应急处置与救援" aria-label="Permalink to &quot;7.4 应急处置与救援 \\*\\*&quot;">​</a></h4><p>应急处置：</p><ul><li>转移、撤离、疏散<strong>受到威胁</strong>的人员</li><li>启用<strong>本级人民政府</strong>的储备物资</li><li>依法<strong>严惩</strong>灾害的囤积物资、哄抬、干扰</li></ul><p>应急救援：</p><ul><li><strong>国务院</strong>或<strong>国务院授权的有关部门</strong>采取措施，保障人民生活需要</li></ul><h4 id="_7-5-事后恢复与重建" tabindex="-1">7.5 事后恢复与重建 * <a class="header-anchor" href="#_7-5-事后恢复与重建" aria-label="Permalink to &quot;7.5 事后恢复与重建 \\*&quot;">​</a></h4><ul><li><strong>人民政府</strong>宣布解除应急响应，结束后<strong>评估并向上级人民政府报告</strong></li><li><strong>国家档案主管部门</strong>建立相应的工作机制档案并移交</li></ul><h3 id="_8-职业病防治法-1-2分" tabindex="-1">8 职业病防治法 1-2分 <a class="header-anchor" href="#_8-职业病防治法-1-2分" aria-label="Permalink to &quot;8 职业病防治法 1-2分&quot;">​</a></h3><h4 id="_8-1-职业病前期预防" tabindex="-1">8.1 职业病前期预防 <a class="header-anchor" href="#_8-1-职业病前期预防" aria-label="Permalink to &quot;8.1 职业病前期预防&quot;">​</a></h4><p>职业病的范围 工作场所的职业卫生要求： <strong>符合国家职业卫生标准</strong> 建设项目职业病危害评价： <strong>可能</strong>产生职业病危害的做<strong>职业病危害预评价</strong> 职业病危害防护设施：<strong>建设</strong>单位应作职业病危害<strong>控制效果评价</strong></p><h4 id="_8-2-劳动过程中的防护与管理" tabindex="-1">8.2 劳动过程中的防护与管理 ** <a class="header-anchor" href="#_8-2-劳动过程中的防护与管理" aria-label="Permalink to &quot;8.2 劳动过程中的防护与管理 \\*\\*&quot;">​</a></h4><p><strong>专职或兼职</strong>职业卫生管理人员 警示：严重职业危害的作业岗位，在醒目位置，设置<strong>警示标识</strong> 监测：专人负责 治理：不符合--治理，依然不符合--必须停止</p><h4 id="_8-3-职业病诊断与职业病病人保障" tabindex="-1">8.3 职业病诊断与职业病病人保障 <a class="header-anchor" href="#_8-3-职业病诊断与职业病病人保障" aria-label="Permalink to &quot;8.3 职业病诊断与职业病病人保障&quot;">​</a></h4><p>职业病诊断：</p><ul><li>取得《医疗机构执业许可证》的医疗机构诊断</li><li>劳动者在用人单位所在地、本人户籍所在地或经常居住地</li><li>诊断需签字盖章</li></ul><p>职业病病人保障</p><ul><li>用人单位：不得解除、终止合同，不宜就调岗</li><li>职业病人：工伤 + 民事赔偿</li></ul><h2 id="第六章-行政法规-23分" tabindex="-1">第六章 行政法规 23分 <a class="header-anchor" href="#第六章-行政法规-23分" aria-label="Permalink to &quot;第六章 行政法规 23分&quot;">​</a></h2><h3 id="_1-安全生产许可证条例-2分" tabindex="-1">1 安全生产许可证条例 2分 <a class="header-anchor" href="#_1-安全生产许可证条例-2分" aria-label="Permalink to &quot;1 安全生产许可证条例 2分&quot;">​</a></h3><h4 id="_1-1-取得安全生产许可证的条件" tabindex="-1">1.1 取得安全生产许可证的条件 ** <a class="header-anchor" href="#_1-1-取得安全生产许可证的条件" aria-label="Permalink to &quot;1.1 取得安全生产许可证的条件 \\*\\*&quot;">​</a></h4><p>安全生产许可制度的适用范围： <strong>烟民建危矿</strong> 取得安全生产许可证的具备条件：</p><ul><li>主要负责人和安全生产管理人员经<strong>考核</strong>合格</li><li>从业人员经安全生产机教育和<strong>培训合格</strong></li><li>设置安全生产管理机构，且配备专职安全生产管理人员</li></ul><h4 id="_1-2-取得安全生产许可证的程序" tabindex="-1">1.2 取得安全生产许可证的程序 * <a class="header-anchor" href="#_1-2-取得安全生产许可证的程序" aria-label="Permalink to &quot;1.2 取得安全生产许可证的程序 \\*&quot;">​</a></h4><p>安全生产许可证申请与延续（记忆<strong>333原则</strong>） 有效期：3年 延续：期满前3个月；守法+无死亡+原机关同意=延期3年</p><p>安全生产许可监督管理的规定</p><ul><li>国务院： 中央管理的危险化学品、烟花爆竹、非煤矿矿山/（中央管理的煤矿--国家煤矿安全监察机构）</li><li>省部门： 其他</li></ul><h3 id="_2-煤矿安全生产条例-2分" tabindex="-1">2 煤矿安全生产条例 2分 <a class="header-anchor" href="#_2-煤矿安全生产条例-2分" aria-label="Permalink to &quot;2 煤矿安全生产条例 2分&quot;">​</a></h3><h4 id="_2-1-煤矿安全生产基本规定" tabindex="-1">2.1 煤矿安全生产基本规定 <a class="header-anchor" href="#_2-1-煤矿安全生产基本规定" aria-label="Permalink to &quot;2.1 煤矿安全生产基本规定&quot;">​</a></h4><p>政府：协调、解决问题 监察机构： 监察检查、组织/参与事故调查处理</p><h4 id="_2-2-煤矿企业的安全生产责任" tabindex="-1">2.2 煤矿企业的安全生产责任 ** <a class="header-anchor" href="#_2-2-煤矿企业的安全生产责任" aria-label="Permalink to &quot;2.2 煤矿企业的安全生产责任 \\*\\*&quot;">​</a></h4><p>审查：省 人员配备： <strong>复杂</strong>水地和及复杂的煤矿--<strong>专职副总工程师</strong> 人员管理： <strong>安全限员</strong>制度/<strong>不允许劳务派遣</strong> 风险隐患： 重大事故隐患故报告+负责签字--每季度报县级人民政府富有职责部门和监察机构 应急救援：专职，不具备+兼职+救护协议</p><h4 id="_2-3-煤矿安全生产监督管理" tabindex="-1">2.3 煤矿安全生产监督管理 ** <a class="header-anchor" href="#_2-3-煤矿安全生产监督管理" aria-label="Permalink to &quot;2.3 煤矿安全生产监督管理 \\*\\*&quot;">​</a></h4><p>政府职责： 省： 明确企业的安全生产监管主体 县： 未取得依法<strong>查处</strong> 乡镇： <strong>有效措施制止</strong>，并向县级报告</p><p>安全生产许可证: 省、自治区、直辖市人民政府负有煤矿安全生产监督管理职责的部门负责颁发、管理</p><p>停产整顿恢复生产: 本部门主要负责人签字 + 所在地矿山安全监察机构审核同意 + 报本级人民政府主要负责人批准</p><h4 id="_2-4-煤矿安全监管监察" tabindex="-1">2.4 煤矿安全监管监察 <a class="header-anchor" href="#_2-4-煤矿安全监管监察" aria-label="Permalink to &quot;2.4 煤矿安全监管监察&quot;">​</a></h4><p>事故报告: 应急管理部门、负有煤矿安全生产监督管理职责的部门和所在矿山安全监察机构</p><p>事故处理: 特别重大事故一一国务院或者国务院授权 重大、较大、一般一一国家矿山安全监察机构、地方的矿山安全监察机构</p><h4 id="_2-5-煤矿安全生产法律责任" tabindex="-1">2.5 煤矿安全生产法律责任 ** <a class="header-anchor" href="#_2-5-煤矿安全生产法律责任" aria-label="Permalink to &quot;2.5 煤矿安全生产法律责任 \\*\\*&quot;">​</a></h4><p>关闭：无证、三月内大于2及以上重大事故隐患、重大灾害</p><h3 id="_3-建设工程安全生产管理条例-1分" tabindex="-1">3 建设工程安全生产管理条例 1分 <a class="header-anchor" href="#_3-建设工程安全生产管理条例-1分" aria-label="Permalink to &quot;3 建设工程安全生产管理条例 1分&quot;">​</a></h3><p>设计： 提意见、提意见 监理：</p><ul><li>审资料</li><li>隐患处理：1改、2停、3报告 设施安装单位： 有资质的单位 施工：</li><li>主要负责人： 建章立制、给钱、定期检查</li><li>项目负责人： 用钱、如实报告事故</li><li>总分包责任： 总负总责，分负分责，总分要连带</li><li>应急预案： 总包统一编，总分各自建</li></ul><h3 id="_4-烟花爆竹安全管理条例-2分" tabindex="-1">4 烟花爆竹安全管理条例 2分 <a class="header-anchor" href="#_4-烟花爆竹安全管理条例-2分" aria-label="Permalink to &quot;4 烟花爆竹安全管理条例 2分&quot;">​</a></h3><h4 id="_4-1-烟花爆竹生产安全" tabindex="-1">4.1 烟花爆竹生产安全 *** <a class="header-anchor" href="#_4-1-烟花爆竹生产安全" aria-label="Permalink to &quot;4.1 烟花爆竹生产安全 \\*\\*\\*&quot;">​</a></h4><ul><li><p>基本规定： 成分组成： <strong>民用黑火药、烟火药、引火线</strong>等 许可制： 生产、经营、运输、举报焰火活动</p><p>部门职责：</p><ul><li>应急部门： <strong>安全生产</strong>监督管理</li><li>公安部： <strong>公共</strong>安全管理</li><li>市场部： <strong>质量监督</strong></li><li>多部门： 查处</li></ul></li><li><p>生产安全规定：</p><ul><li>安全生产许可证： 市应急提意见、省应急审查</li><li>生产企业： ① 申请 ② 审查 ③ 登记</li><li>危险工序人员： 市应急考核合格</li><li>原料丢失： 包当地应急 + 公安部门</li></ul></li></ul><h4 id="_4-2-烟花爆竹经营与运输安全" tabindex="-1">4.2 烟花爆竹经营与运输安全 ** <a class="header-anchor" href="#_4-2-烟花爆竹经营与运输安全" aria-label="Permalink to &quot;4.2 烟花爆竹经营与运输安全 \\*\\*&quot;">​</a></h4><p>许可： 卖的经--<strong>应急管理部门审批</strong>，运的经--<strong>公安部门</strong>许可 零售： <strong>县级</strong>应急申请，30日内进行审查 批发： <strong>市级</strong>应急申请，20日内进行审查（向生产企业购买） 烟花爆竹运输许可申请：<strong>托运人</strong>在<strong>运达地</strong>向<strong>县级人民政府公安机关</strong>申请，收货3日内核销许可证</p><h4 id="_4-3-烟花爆竹燃放安全" tabindex="-1">4.3 烟花爆竹燃放安全 * <a class="header-anchor" href="#_4-3-烟花爆竹燃放安全" aria-label="Permalink to &quot;4.3 烟花爆竹燃放安全 \\*&quot;">​</a></h4><p>大型焰火： <strong>20日</strong>，公安机关审查 禁止燃放： 政府规定</p><h3 id="_5-民用爆炸物品安全管理条例-2分" tabindex="-1">5 民用爆炸物品安全管理条例 2分 <a class="header-anchor" href="#_5-民用爆炸物品安全管理条例-2分" aria-label="Permalink to &quot;5 民用爆炸物品安全管理条例 2分&quot;">​</a></h3><h4 id="_5-1-民用爆炸物品的生产要求" tabindex="-1">5.1 民用爆炸物品的生产要求 ** <a class="header-anchor" href="#_5-1-民用爆炸物品的生产要求" aria-label="Permalink to &quot;5.1 民用爆炸物品的生产要求 \\*\\*&quot;">​</a></h4><p>范围：</p><ul><li>民爆物品 + <strong>硝酸铵</strong></li><li>用途： <strong>非军事目的</strong></li></ul><p>主体：</p><ul><li>无民事行为能力、限制民事行为能力人、曾犯罪<strong>受过刑事处罚</strong>的人，不得从事相关作业</li></ul><p>部门：</p><ul><li>民爆行业部： <strong>生产、销售</strong></li><li>公安机关： <strong>公共安全</strong> -- 运输、购买、流向、爆破</li></ul><p>查处： 民爆主管部门、公安机关、工伤行政管理部门查处非法</p><p>生产条件、标准： <strong>国家产业结构</strong>、<strong>国家标准</strong></p><p>证件：</p><ul><li>先<strong>生产许可</strong>--办证（<strong>国务院民爆行业主管部</strong>）、登记（工商局）、备案（<strong>3日内县级公安机关</strong>）；</li><li>再<strong>安全生产许可</strong>--申请（<strong>省民爆行业主管部</strong>）、发证、生产</li></ul><p>试验： <strong>专门的场地</strong>或<strong>专门的实验室</strong>试验</p><h4 id="_5-2-销售、购买的要求" tabindex="-1">5.2 销售、购买的要求 ** <a class="header-anchor" href="#_5-2-销售、购买的要求" aria-label="Permalink to &quot;5.2 销售、购买的要求 \\*\\*&quot;">​</a></h4><p>销售许可：</p><ul><li>办证： <strong>省民爆</strong>部门</li><li>登记： 工商登记</li><li>备案： <strong>3日内</strong> + <strong>县公安机关</strong></li></ul><p>购买许可：</p><ul><li><strong>县公安机关</strong>提出购买申请</li><li>需要资料： <strong>购买单位的名称、地址、银行账户</strong></li></ul><p>特殊规定：</p><ul><li><strong>银行交易</strong>、不得现金或实物交易</li><li>交易记录： <strong>2年</strong>备查</li><li>卖方备案： 卖<strong>3日内</strong>，**省民爆主管部门 + 县级公安机关 **</li><li>买方备案： 买<strong>3日内</strong>，<strong>县级公安机关</strong></li></ul><h4 id="_5-3-运输、储存的要求" tabindex="-1">5.3 运输、储存的要求 * <a class="header-anchor" href="#_5-3-运输、储存的要求" aria-label="Permalink to &quot;5.3 运输、储存的要求 \\*&quot;">​</a></h4><p>运输：</p><ul><li>民爆运输许可证： <strong>收货单位 + 运达地 + 县级公安机关</strong>办理，运达 -- <strong>3日</strong>内发证机关<strong>核销</strong></li><li>记忆区分：<strong>剧毒、烟花运运输许可证（托运人）办理 -- 民爆运输（收货单位）；剧毒 -- 始发地或目的地，烟花、民爆（运达地）办理</strong></li><li>运输过程： <strong>出危险 = 应急措施 + 当地公安机关，停 -- 专人看守</strong></li></ul><p>储存：</p><ul><li>存储管理：专用仓库，临时存储时需要具备<strong>临时存放</strong>条件，并有<strong>专人</strong>看护</li><li>销毁： 过期及时出库销毁，报<strong>省民爆主管部门</strong>、<strong>县级公安机关</strong>组织监督销毁</li><li>分库： <strong>性质相抵触</strong>的民爆<strong>必须分库</strong>存储</li><li>专人： 专人管理、看护</li><li>丢失、被盗： 报<strong>当地公安机关</strong></li></ul><h4 id="_5-4-爆破作业的安全管理" tabindex="-1">5.4 爆破作业的安全管理 * <a class="header-anchor" href="#_5-4-爆破作业的安全管理" aria-label="Permalink to &quot;5.4 爆破作业的安全管理 \\*&quot;">​</a></h4><p>爆破作业单位许可证：</p><ul><li>办证： 向<strong>公安机关</strong>申请，申请起<strong>20日</strong>内进行审查</li><li>登记： 工商登记</li><li>备案： 工商登记后<strong>3日</strong>向所在<strong>县级公安机关</strong>备案</li><li>特殊： 在城市、风景、重要工程附件，还需向<strong>市级公安机关</strong>提出申请；还需有资质的<strong>安全监理企业进行监理</strong>，由所在<strong>县级公安机关</strong>实施安全警戒</li></ul><p>爆破作业人员：</p><ul><li>培训: 经<strong>市级公安机关</strong>考核合格，取得爆破作业人员许可证才有爆破作业</li><li>记忆区分： 烟花爆竹危险工序作业人员经<strong>市级应急管理部门</strong>考核合格</li></ul><p><strong>记忆区分</strong>：</p><ul><li>申请-审查-登记-备案： 民爆生产许可、民爆销售许可、民爆作业许可</li><li>申请-审查-登记： 烟花爆竹安全生产许可、危险化学品经营许可</li><li>申请： 其他</li></ul><h3 id="_6-特种设备安全监察条例-1分" tabindex="-1">6 特种设备安全监察条例 1分 <a class="header-anchor" href="#_6-特种设备安全监察条例-1分" aria-label="Permalink to &quot;6 特种设备安全监察条例 1分&quot;">​</a></h3><p>特种设备的生产、使用</p><ul><li>生产： <strong>施工单位</strong>应在验收<strong>30内</strong>相关资料移交<strong>使用单位</strong></li><li>维护保养： 至少每月一次</li><li>定期检验： 届满前<strong>1个月</strong>提出定期检验要求</li><li>索道、大型游乐： 每月一次会议</li><li><strong>加强记忆</strong>： 索道、大型游乐--每日，电梯--15日，其他--每月</li></ul><p>检验检测</p><ul><li>检查机构： 国务院核准</li><li>检查人员： 国务院考核合格</li></ul><p>特种设备的预防和调查处理： 事故判断表格：</p><table tabindex="0"><thead><tr><th style="text-align:center;">判定指标</th><th style="text-align:center;">一般事故</th><th style="text-align:center;">较大事故</th><th style="text-align:center;">重大事故</th><th style="text-align:center;">特别重大事故</th></tr></thead><tbody><tr><td style="text-align:center;">死亡人数</td><td style="text-align:center;">&lt;3人</td><td style="text-align:center;">3~9人</td><td style="text-align:center;">10~29人</td><td style="text-align:center;">≥30人</td></tr><tr><td style="text-align:center;">重伤人数</td><td style="text-align:center;">&lt;10人</td><td style="text-align:center;">10~49人</td><td style="text-align:center;">50~99人</td><td style="text-align:center;">≥100人</td></tr><tr><td style="text-align:center;">直接经济损失</td><td style="text-align:center;">&lt;1000万元</td><td style="text-align:center;">1000万~5000万元</td><td style="text-align:center;">5000万~1亿元</td><td style="text-align:center;">≥1亿元</td></tr><tr><td style="text-align:center;">人员转移</td><td style="text-align:center;">&lt;1万以下</td><td style="text-align:center;">1万~5万人</td><td style="text-align:center;">5万~15万人</td><td style="text-align:center;">≥15万人</td></tr><tr><td style="text-align:center;">事故类型</td><td style="text-align:center;">折断、坠落</td><td style="text-align:center;">爆炸、整体倾斜</td><td style="text-align:center;">600兆瓦锅炉、中断≥24H</td><td style="text-align:center;">600兆瓦锅炉爆炸</td></tr><tr><td style="text-align:center;">滞留时间</td><td style="text-align:center;">12H以下</td><td style="text-align:center;">12H~24H</td><td style="text-align:center;">24H-48H</td><td style="text-align:center;">48H以上</td></tr><tr><td style="text-align:center;">调查部门</td><td style="text-align:center;">市</td><td style="text-align:center;">省</td><td style="text-align:center;">国务院部门</td><td style="text-align:center;">国务院</td></tr></tbody></table><p>加强记忆： 313、151、151</p><h3 id="_7-生产安全事故应急条例-4分" tabindex="-1">7 生产安全事故应急条例 4分 <a class="header-anchor" href="#_7-生产安全事故应急条例-4分" aria-label="Permalink to &quot;7 生产安全事故应急条例 4分&quot;">​</a></h3><h4 id="_7-1-基本规定-1" tabindex="-1">7.1 基本规定： *** <a class="header-anchor" href="#_7-1-基本规定-1" aria-label="Permalink to &quot;7.1 基本规定： \\*\\*\\*&quot;">​</a></h4><p>事故应急体系：</p><ul><li>国务院：<strong>全国</strong>的生产安全事故应急工作</li><li><em>县级人民政府</em>的： <strong>本行政区域内</strong>的生产安全事故应急工作</li><li>乡镇： <strong>协助</strong>上级人民政府依法生产事故应急工作职责</li></ul><p>应急救援队伍：</p><ul><li>县级人民政府统一规划、组织和指导</li><li>县级人民政府根据<strong>实际需要</strong>单独建立或者依托有条件的建立</li><li>建立应急救援队伍： ① 危建道金矿+人密， ② 大中型；</li><li>可不建，配兼职： 小型</li><li>可以联合建立： 工业园区、开发区等</li><li>培训：<strong>建立单位</strong>或<strong>者兼职所在单位</strong>培训合格</li></ul><h4 id="_7-2-应急准备" tabindex="-1">7.2 应急准备： *** <a class="header-anchor" href="#_7-2-应急准备" aria-label="Permalink to &quot;7.2 应急准备： \\*\\*\\*&quot;">​</a></h4><p>应急预案的制定与备案：</p><ul><li>政府： <ul><li>制定: 针对<strong>可能发生</strong>的生产安全事故，制定<strong>相应</strong>的预案，并<strong>向社会公布</strong></li><li>备案： <strong>部门</strong>找<strong>本级人民政府</strong>去备案</li></ul></li><li>单位： <ul><li>制定: 针对本单位<strong>可能发生</strong>的生产安全事故，制定<strong>相应</strong>的预案，并<strong>从业人员</strong>公布</li><li>备案： <strong>危建道金矿+人密</strong>找<strong>县级部门</strong>去备案，并向社会公布</li></ul></li></ul><p>应急预案的演练：</p><ul><li>政府： 每2年组织一次，</li><li>单位： 危建道金矿+人密 = 只是半年一次，并报县级负有部门</li></ul><h4 id="_7-3-应急救援" tabindex="-1">7.3 应急救援： ** <a class="header-anchor" href="#_7-3-应急救援" aria-label="Permalink to &quot;7.3 应急救援： \\*\\*&quot;">​</a></h4><p>应急值班制定：</p><ul><li>县政府+部门</li><li>危建道金矿</li><li>应急救援队伍：<strong>规模大、危险较高</strong> + <strong>易燃易爆、危险化学平</strong>的生产、经营、储存、运输应当建立并<strong>24小时应急值班</strong></li></ul><p>应急救援措施 -- 单位：</p><ul><li><strong>根据事故危害程度</strong>，组织现场人员<strong>撤离</strong>或者<strong>采取可能的应急措施后撤离</strong></li><li>及时通知可能世道影响的单位和人员</li></ul><p>应急救援措施 -- 政府：</p><ul><li>隔离事故现场，划定警戒区域，疏散<strong>受到威胁</strong>的人员，实施交通管制</li><li><strong>发布调用和征用</strong>应急资源的决定</li></ul><h3 id="_8-生产安全事故报告和调查处理条例-4分" tabindex="-1">8 生产安全事故报告和调查处理条例 4分 <a class="header-anchor" href="#_8-生产安全事故报告和调查处理条例-4分" aria-label="Permalink to &quot;8 生产安全事故报告和调查处理条例 4分&quot;">​</a></h3><h4 id="_8-1-事故报告" tabindex="-1">8.1 事故报告： *** <a class="header-anchor" href="#_8-1-事故报告" aria-label="Permalink to &quot;8.1 事故报告： \\*\\*\\*&quot;">​</a></h4><p>事故等级： 313，151，151</p><p>事故报告流程：</p><ul><li>民报名： 立即</li><li>民报官： 1小时，特殊现场直接报官</li><li>官报官： 2小时</li></ul><p>事故续报、补报：</p><ul><li>事故发生<strong>30日内</strong>，上伤亡人数发生变化及时补报</li><li><strong>道路安全事故、火灾事故</strong>自发是<strong>7日内</strong>人员变化补报</li></ul><h4 id="_8-2-事故调查" tabindex="-1">8.2 事故调查： *** <a class="header-anchor" href="#_8-2-事故调查" aria-label="Permalink to &quot;8.2 事故调查： \\*\\*\\*&quot;">​</a></h4><ul><li>调查：是<strong>政府</strong>不是部门</li><li>委托： 可以委托、授权有关部门组织调查</li><li>特殊：单位<strong>未造成</strong>人员死亡的<strong>一般事故</strong>，县可以委托事故单位调查</li><li>事故鉴定： <strong>需要</strong>技术鉴定所需时间不计入<strong>事故调查期限</strong></li><li>事故调查报告：自发之日起<strong>60日</strong>提交调查报告</li><li>批复： <strong>特别重大30内日</strong>，其他<strong>15日内</strong></li><li>评估： 在批复后<strong>1年内</strong>组织评估</li></ul><h3 id="_9-工伤保险条例-4分" tabindex="-1">9 工伤保险条例 4分 <a class="header-anchor" href="#_9-工伤保险条例-4分" aria-label="Permalink to &quot;9 工伤保险条例 4分&quot;">​</a></h3><h4 id="_9-1-工伤保险基金" tabindex="-1">9.1 工伤保险基金 ** <a class="header-anchor" href="#_9-1-工伤保险基金" aria-label="Permalink to &quot;9.1 工伤保险基金 \\*\\*&quot;">​</a></h4><p>工伤保险的适用范围：</p><ul><li>适用： 单位给所有职工</li><li>不适用： <strong>公务员和参照公务员法管理</strong>的事业单位、社会团体员工或职业病由所在单位支付</li></ul><p>缴纳工伤保险费的规定：</p><ul><li>原则： 收支平衡</li><li>制定: 根据行业的差别费率分若干等级</li><li>批准： <strong>部门</strong>制定，<strong>国务院</strong>批准</li></ul><p>工伤保险基金的适用：</p><ul><li>用途： 工伤保险待遇，劳动能力鉴定，工伤预防的宣传、培训等费用</li><li>管理： 单位、个人不得用于其他用途</li><li>储备金： 储备金，用于<strong>重大事故</strong>的工伤支付，不够的情况<strong>政府垫付</strong></li></ul><h4 id="_9-2-工伤的认定" tabindex="-1">9.2 工伤的认定 ** <a class="header-anchor" href="#_9-2-工伤的认定" aria-label="Permalink to &quot;9.2 工伤的认定 \\*\\*&quot;">​</a></h4><p>工伤范围：</p><ul><li>工作地点 、工作时间、与工作有关、职业病、因工作出差由工作原因、上下班途中<strong>非本人责任的交通事故</strong></li><li>视为工伤： 工作时间、岗位，<strong>突发疾病死亡</strong>或<strong>48小时内</strong>抢救无效</li><li>不视为： 故意犯罪、自杀、醉酒</li></ul><p>工伤认定的申请时限：</p><ul><li>申请： 单位--30日内，个人、或近亲属、工会组织--发生事故或被诊断<strong>1年内</strong></li></ul><p>工伤认定的申请材料：</p><ul><li>工伤认定程序：</li><li>调查核实： 根据审核需要相应的个人、单位需要协助；已经取得诊断书的不在进行调查核实</li><li>举证： 个人认为是，单位认为不是，用人单位举证</li><li>认定的决定： 申请的<strong>60日内</strong>做出决定；事实清楚、权利义务明确的应在<strong>15日内</strong>决定</li></ul><h4 id="_9-3-劳动能力鉴定" tabindex="-1">9.3 劳动能力鉴定 * <a class="header-anchor" href="#_9-3-劳动能力鉴定" aria-label="Permalink to &quot;9.3 劳动能力鉴定 \\*&quot;">​</a></h4><ul><li>伤残等级： 1-10级，1级最重</li><li>生活自理等级： 1-3级（完全不能、大部分不能、部分不能）</li><li>申请： 单位、个人或近亲属向<strong>市级劳动能力委员会</strong>申请</li><li>鉴定主体： <strong>市</strong>抽取<strong>3名</strong>或<strong>5名</strong>专家组</li><li>鉴定时间： <strong>60日内</strong>劳动能力鉴定，必要时可延长<strong>30日</strong></li><li>不服、结论： <strong>15日内</strong>向省提申请，省给<strong>最终结论</strong></li><li>复查鉴定： <strong>1年后</strong>可以复查鉴定</li></ul><h4 id="_9-4-工伤保险待遇" tabindex="-1">9.4 工伤保险待遇 *** <a class="header-anchor" href="#_9-4-工伤保险待遇" aria-label="Permalink to &quot;9.4 工伤保险待遇 \\*\\*\\*&quot;">​</a></h4><p>工伤医疗补偿和待遇伤残待遇：</p><ul><li>签到医疗机构，<strong>情况紧急</strong>先<strong>就近</strong>急救</li><li>伤残待遇： <ul><li>1-4级： 保留劳动关系，退出工作岗位--支付一次性伤残金（1级=27月工资，2级=25月，3级=23月，4级=21月）--<strong>工伤保险基金</strong>按月伤残津贴（1级=90%工资，2级=85%,3级=80%，4级=75%）不足当地最低工资由工伤保险基金补差额</li><li>5-6级： 保留劳动关系，安排适当工作--支付一次性伤残金（5级=18月工资，6级=16月），--无法安排工作，<strong>用人单位</strong>按月伤残津贴（5级=70%，6级=60%），不足当地最低工资由单位补差额</li></ul></li></ul><p>停工期间的福利：</p><ul><li>按月支付--<strong>不超过12个月</strong>，经市级劳动能力鉴定委员会，可延长也不得超过<strong>12个月</strong>，不能自理<strong>单位</strong>支付护理费</li></ul><p>护理费： 工伤保险基金<strong>按月</strong>支付，完全=统筹的50%，大部分=40%，部门=30%</p><p>职工死亡、伤残的待遇：</p><ul><li>丧葬补助金、供养亲属抚恤金和一次性工亡补助金</li><li>丧葬补助金: 统筹6个月</li><li>供养亲属抚恤金： 配偶40%，其他亲属每人30%，孤寡老人或孤儿基础上加10%</li><li>一次性工亡补助金： 全国城镇居民人均可支配<strong>20倍</strong></li><li>下落不明：<strong>3个月内</strong>照发工资</li></ul><h4 id="_9-5-工伤保险责任" tabindex="-1">9.5 工伤保险责任 * <a class="header-anchor" href="#_9-5-工伤保险责任" aria-label="Permalink to &quot;9.5 工伤保险责任 \\*&quot;">​</a></h4><ul><li>转让、合并： 继承单位 = 劳动关系</li><li>借调： 原单位</li><li>破产： 用人单位</li></ul><h3 id="_10-大型群众性活动安全管理条例-1分必考" tabindex="-1">10 大型群众性活动安全管理条例 1分必考 <a class="header-anchor" href="#_10-大型群众性活动安全管理条例-1分必考" aria-label="Permalink to &quot;10 大型群众性活动安全管理条例 1分必考&quot;">​</a></h3><h4 id="_10-1-基本规定" tabindex="-1">10.1 基本规定 * <a class="header-anchor" href="#_10-1-基本规定" aria-label="Permalink to &quot;10.1 基本规定 \\*&quot;">​</a></h4><ul><li>范围： 法人其他组织面向<strong>社会公众</strong>人数达<strong>1000人以上</strong></li><li>特殊除外： 影视院、音乐厅、公园、娱乐场所等<strong>日常业务范围内</strong>的除外</li></ul><h4 id="_10-2-安全责任" tabindex="-1">10.2 安全责任 ** <a class="header-anchor" href="#_10-2-安全责任" aria-label="Permalink to &quot;10.2 安全责任 \\*\\*&quot;">​</a></h4><ul><li>安全许可： <ul><li>原则： 应当遵循<em>安全第一、预防为主</em>的方针，坚持<strong>承办者责任、政府监督</strong>的原则</li><li>部门： 公安机关</li><li>申请： <strong>承办方</strong>活动前20日提出安全许可申请--1000~5000人县公安，5000人以上市级公安，跨省国务院公安</li></ul></li><li>安全责任： <ul><li>公安： 安全许可</li></ul></li></ul><h3 id="_11-女职工劳动保护特别规定-1分必考" tabindex="-1">11 女职工劳动保护特别规定 1分必考 <a class="header-anchor" href="#_11-女职工劳动保护特别规定-1分必考" aria-label="Permalink to &quot;11 女职工劳动保护特别规定 1分必考&quot;">​</a></h3><h4 id="_11-1-女职工禁忌从事的劳动范围" tabindex="-1">11.1 女职工禁忌从事的劳动范围 ** <a class="header-anchor" href="#_11-1-女职工禁忌从事的劳动范围" aria-label="Permalink to &quot;11.1 女职工禁忌从事的劳动范围 \\*\\*&quot;">​</a></h4><p>禁忌范围：</p><ul><li>不下矿井，四集不干，6次 + 20公斤以上，间断 + 超过25公斤</li><li>特殊禁忌： <ul><li>经期--冷水2~4级、低温2~4级，体力3~4级，高处3~4级；</li><li>孕期--低冷+高处，高温、噪音、体力3~4，<strong>强烈震动</strong>或<strong>频繁弯腰</strong>，非密封源放射物质</li><li>哺乳期--有毒、非密封源放射物质，体力3~4</li></ul></li></ul><p>记忆巩固：<strong>不三不四，不怕高温，孕期高冷</strong></p><h4 id="_11-2-女职工生育保护" tabindex="-1">11.2 女职工生育保护 * <a class="header-anchor" href="#_11-2-女职工生育保护" aria-label="Permalink to &quot;11.2 女职工生育保护 \\*&quot;">​</a></h4><ul><li>孕期7月上/哺乳期1岁：不加班、不夜班</li></ul><h2 id="第七章-安全生产部门规章-27分" tabindex="-1">第七章 安全生产部门规章 27分 <a class="header-anchor" href="#第七章-安全生产部门规章-27分" aria-label="Permalink to &quot;第七章 安全生产部门规章 27分&quot;">​</a></h2><h3 id="_1-注册安全工程师分类管理办法" tabindex="-1">1 注册安全工程师分类管理办法 <a class="header-anchor" href="#_1-注册安全工程师分类管理办法" aria-label="Permalink to &quot;1 注册安全工程师分类管理办法&quot;">​</a></h3><h4 id="_1-1-注册安全工程师的类别和配备人数" tabindex="-1">1.1 注册安全工程师的类别和配备人数 ** <a class="header-anchor" href="#_1-1-注册安全工程师的类别和配备人数" aria-label="Permalink to &quot;1.1 注册安全工程师的类别和配备人数 \\*\\*&quot;">​</a></h4><p>类别：</p><ul><li>煤矿安全、金属非金属矿山安全、</li><li>初中高级</li></ul><p>继续教育：</p><ul><li><strong>累计不少于48小时</strong></li><li>中级<strong>专业课时</strong>应<strong>不少于继续教育总学时的一半</strong>（24学时）</li></ul><p>配备：</p><ul><li>危金矿： <strong>中级及以上</strong>达到**15%**左右并逐步提高</li><li>中介机构： <strong>30%以上</strong>比例</li></ul><h4 id="_1-2-注册要求" tabindex="-1">1.2 注册要求 *** <a class="header-anchor" href="#_1-2-注册要求" aria-label="Permalink to &quot;1.2 注册要求 \\*\\*\\*&quot;">​</a></h4><p>执业范围：</p><ul><li><strong>参与并签署意见</strong></li><li>制定从业人员<strong>安全培训计划</strong></li><li>选用和发放<strong>劳动防护用品</strong></li><li>生产安全<strong>事故调查</strong></li></ul><p>注册安全工程师的权利和义务：</p><ul><li>权利： 称谓、提建议、继续教育</li><li>义务： 承担责任、保守秘密、继续教育、本人报告署名，不得同时在两个及以上受聘</li></ul><p>注册：</p><ul><li>具备民事行为能力，不超过70岁</li><li>初始注册： 5年内注册，</li><li>有效期： 5年</li><li>延续注册： 有效期满<strong>前3个月</strong></li></ul><h3 id="_2-生产经营单位安全培训规定-2-3分" tabindex="-1">2 生产经营单位安全培训规定 2~3分 <a class="header-anchor" href="#_2-生产经营单位安全培训规定-2-3分" aria-label="Permalink to &quot;2 生产经营单位安全培训规定 2~3分&quot;">​</a></h3><h4 id="_2-1-从业人员的安全培训" tabindex="-1">2.1 从业人员的安全培训 *** <a class="header-anchor" href="#_2-1-从业人员的安全培训" aria-label="Permalink to &quot;2.1 从业人员的安全培训 \\*\\*\\*&quot;">​</a></h4><p>安全培训的学时要求：</p><table tabindex="0"><thead><tr><th style="text-align:left;">企业类型</th><th style="text-align:left;">人员类型</th><th style="text-align:center;">初次培训</th><th style="text-align:center;">再培训</th></tr></thead><tbody><tr><td style="text-align:left;">高危企业</td><td style="text-align:left;">主要负责人和管理人员</td><td style="text-align:center;">48</td><td style="text-align:center;">16</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">新上岗从业人员</td><td style="text-align:center;">72</td><td style="text-align:center;">20</td></tr><tr><td style="text-align:left;">非高危企业</td><td style="text-align:left;">主要负责人和管理人员</td><td style="text-align:center;">32</td><td style="text-align:center;">12</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">新上岗从业人员</td><td style="text-align:center;">24</td><td style="text-align:center;">——</td></tr></tbody></table><blockquote><p>高危： <strong>危金矿+烟花爆竹</strong></p></blockquote><p>安全培训的上岗要求：</p><ul><li>三级安全培训： 厂、车间、班组</li><li>内容： 三个都有<strong>有关事故案例</strong>，厂--单位，车间--工种、车间，班组--岗位</li></ul><p>重新上岗培训：</p><ul><li>调岗或离岗1年以上： 需接受<strong>车间和岗位</strong>的培训</li><li>新设备、新技术： 重新进行培训</li></ul><p>实习期上岗：</p><ul><li>不得单独，考试合格后<strong>由班组组织</strong></li></ul><p>部门考核：</p><ul><li><strong>危金矿+烟花爆竹</strong>--主要<strong>负责人和安全生产管理人员</strong>自任职<strong>6个月内</strong>，安全生产监管监察<strong>部门</strong>考核合格</li></ul><h4 id="_2-2-安全培训的组织实施" tabindex="-1">2.2 安全培训的组织实施 ** <a class="header-anchor" href="#_2-2-安全培训的组织实施" aria-label="Permalink to &quot;2.2 安全培训的组织实施 \\*\\*&quot;">​</a></h4><p>安全培训的组织：</p><ul><li>危金矿+烟花爆竹： <strong>师傅带徒弟</strong>制定</li></ul><p>安全培训的主体：</p><ul><li>具备：自己培训或<strong>可以</strong>委托培训</li><li>不具备： <strong>应当</strong>委托培训</li></ul><p>生产经营单位安全培训的职责：</p><h3 id="_3-特种作业人员安全技术培训考核管理规定-5分" tabindex="-1">3 特种作业人员安全技术培训考核管理规定 5分 <a class="header-anchor" href="#_3-特种作业人员安全技术培训考核管理规定-5分" aria-label="Permalink to &quot;3 特种作业人员安全技术培训考核管理规定 5分&quot;">​</a></h3><h4 id="_3-1-基本规定" tabindex="-1">3.1 基本规定 *** <a class="header-anchor" href="#_3-1-基本规定" aria-label="Permalink to &quot;3.1 基本规定 \\*\\*\\*&quot;">​</a></h4><p>特种作业人员的范围：</p><ul><li>危金矿+烟花爆竹+电工+高除作业+焊接热切割+石油天然气</li></ul><p>特种作业人员的条件：</p><ul><li>18岁且不超过国家法定年龄</li><li>无疾病、眩晕症等</li><li>危金矿+烟花爆竹+电工+高除作业+焊接热切割+石油天然气--<strong>初中及以上</strong>文化程度</li><li><strong>危险化学品特种作业、首次取证地下矿山特种作业</strong>--<strong>高中及以上</strong>文化程度</li></ul><h4 id="_3-2-特种作业人员的培训、考核与发证" tabindex="-1">3.2 特种作业人员的培训、考核与发证 *** <a class="header-anchor" href="#_3-2-特种作业人员的培训、考核与发证" aria-label="Permalink to &quot;3.2 特种作业人员的培训、考核与发证 \\*\\*\\*&quot;">​</a></h4><p>特种作业人员培训考核体系：</p><ul><li>原则与要求： 原则--分级实施、考培分类，要求--特种作业证</li><li>监督部门与职责： <ul><li>应急管理部门：监督全国特种作业的培训、考核、发证、换证，省本行政内</li><li>矿山安全监督部门： 国家矿山安全监督局</li></ul></li></ul><p>特种作业人员的安全培训：</p><ul><li>具备：自己培训或<strong>可以</strong>委托培训</li><li>不具备： <strong>应当</strong>委托培训</li></ul><p>特种作业人员的考核与发证：</p><ul><li>考核： <ul><li>考核内容--安全技术考试和资格审核</li><li>考核主体--考核发证机关自己或者委托考试机构实施，发证由机关</li><li>考核内容--考核发证机关自己或者委托考试机构符合规定的考试点</li></ul></li><li>考核程序： <ul><li>申请--① 自己或委托他人向考核机关提出申请 ② 学历要求及相应资料 ③ 可以免考试的提供证明</li><li>审查--考核发证机关自己或者委托考试机构对申请资料审查，并<strong>5个工作日</strong>给出结果告知申请人</li><li>组织考试--发布定期开始计划，并收到申请后<strong>60日内</strong>组织考试</li><li>考试结果--理论+实操，理论过方可实操--实操没过可5次重考，在不过重考理论；申请后<strong>3年内</strong>完成考试</li><li>成绩公布--考试结束后<strong>10个工作日</strong>公布成绩</li></ul></li><li>发证： <ul><li>申请--自己或委托他人向考核发证机关申请特作业证</li><li>审核--考核发证机关受理<strong>20个工作日</strong>审查</li><li>有效期--特作业证有效期<strong>6年</strong></li></ul></li><li>丢失变更: <ul><li><strong>原发证机关</strong>申请</li></ul></li></ul><h4 id="_3-3-特种作业操作证换证" tabindex="-1">3.3 特种作业操作证换证 ** <a class="header-anchor" href="#_3-3-特种作业操作证换证" aria-label="Permalink to &quot;3.3 特种作业操作证换证 \\*\\*&quot;">​</a></h4><p>换证情形：</p><ul><li>证间到期</li><li>特殊情况可以延期换证申请，证件届满后<strong>最长不超过2年</strong>，延期内不得作业</li><li>失效<strong>1年内</strong>按换证，超一年按<strong>首次取证</strong>办理，失效期间不得从业</li></ul><p>换证程序：</p><ul><li>申请： <ul><li>有效期<strong>6个月内</strong>，完成安全技术理论培训和理论考试，并且在<strong>有效期届满前60日内</strong>换证申请</li></ul></li><li>受理： <ul><li>受理<strong>20个工作日</strong>完成审查工作</li></ul></li></ul><h4 id="_3-4-监督管理与法律责任承担" tabindex="-1">3.4 监督管理与法律责任承担 * <a class="header-anchor" href="#_3-4-监督管理与法律责任承担" aria-label="Permalink to &quot;3.4 监督管理与法律责任承担 \\*&quot;">​</a></h4><p>监督管理：</p><ul><li>撤销： <strong>3年内</strong>不得再次申请</li><li>注销：</li></ul><p>罚则：</p><ul><li>无证上岗: <strong>责令改正</strong>，处10W一下罚款；<strong>逾期未改</strong>，<strong>停产停业</strong>，并处10W~20W罚款，对其直接责任的主管人员和其他直接责任人处2W~5W罚款</li><li>档案未建立： <ul><li>单位： 责令--2W以下,逾期--2W~5W</li><li>机构： 责令--2W以下,逾期--2W~5W</li></ul></li></ul><h3 id="_4-安全生产培训管理办法-1分" tabindex="-1">4 安全生产培训管理办法 1分 <a class="header-anchor" href="#_4-安全生产培训管理办法-1分" aria-label="Permalink to &quot;4 安全生产培训管理办法 1分&quot;">​</a></h3><h4 id="_4-1-基本规定" tabindex="-1">4.1 基本规定 <a class="header-anchor" href="#_4-1-基本规定" aria-label="Permalink to &quot;4.1 基本规定&quot;">​</a></h4><p>培训大纲的制度：</p><ul><li>国务院： 危金矿的主要负责人和安全生产管理人员、特种作业以及从事安全生产相关人（国家矿山--安全监督局）</li><li>省级部门： 除危金矿</li></ul><h4 id="_4-2-安全培训" tabindex="-1">4.2 安全培训 <a class="header-anchor" href="#_4-2-安全培训" aria-label="Permalink to &quot;4.2 安全培训&quot;">​</a></h4><ul><li>安全培训： <ul><li>原则： 分级实施、分类指导</li><li>要求： <strong>危金矿+特种+注</strong>--书面<strong>报告所在地应急部门</strong></li></ul></li><li>部门职责 <ul><li>国务院应急部--负责省及以上应急管部门的安全上产监管人员</li><li>省应急部--省以下应急管理部门的安全生产监管人员的培训工作</li></ul></li><li>单位的安全生产培训 <ul><li>重新参加安全培训： 死亡--<strong>单位主要责任人</strong>和安全生产<strong>管理人员</strong>重新培训；与<strong>特作业人</strong>有<strong>直接关系</strong>就得重新培训</li><li>新招井下人培训要求： 井下和危险工艺人，应培训，还需有经验的带实习<strong>满2个月</strong></li><li>职校培训要求: 相关专业，<strong>可免参与初次培训，实际操作培训除外</strong></li></ul></li></ul><h4 id="_4-3-考核与发证" tabindex="-1">4.3 考核与发证 <a class="header-anchor" href="#_4-3-考核与发证" aria-label="Permalink to &quot;4.3 考核与发证&quot;">​</a></h4><ul><li>国务院应急: 央企总公司主管</li><li>省应急： 央企子主管+特种作业</li><li>市应急： 其他单位主管</li><li>特种作业操作证、省级主管证书： 全国有效</li></ul><h3 id="_5-安全生产事故隐患排查治理暂行规定-3分" tabindex="-1">5 安全生产事故隐患排查治理暂行规定 3分 <a class="header-anchor" href="#_5-安全生产事故隐患排查治理暂行规定-3分" aria-label="Permalink to &quot;5 安全生产事故隐患排查治理暂行规定 3分&quot;">​</a></h3><h4 id="_5-1-基本规定-1" tabindex="-1">5.1 基本规定 *** <a class="header-anchor" href="#_5-1-基本规定-1" aria-label="Permalink to &quot;5.1 基本规定 \\*\\*\\*&quot;">​</a></h4><p>事故隐患分级:</p><ul><li>一般事故隐患： 危害小，<strong>能立即整改</strong>排除</li><li>重大事故隐患： 危害大，部门或全部停产，并<strong>经一定时间整改</strong>排除</li></ul><p>生产经营单位事故隐患排查治理职责：</p><ul><li>生产经营单位负责</li><li>生产经营单位应每季、每年对本单位事故隐患排查，并于<strong>下季度15日前</strong>和<strong>下一年1月31日</strong>向安全监管检查部及有关部书面统计并<strong>单位主要负责人</strong>签字</li></ul><p>重大事故隐患报告：</p><ul><li>事故隐患治理</li><li>自然灾害预警</li><li>治理后的安全评估</li><li>重大事故隐患治理的监督检查</li></ul><h4 id="_5-2-监督管理" tabindex="-1">5.2 监督管理 *** <a class="header-anchor" href="#_5-2-监督管理" aria-label="Permalink to &quot;5.2 监督管理 \\*\\*\\*&quot;">​</a></h4><p>事故隐患治理：</p><ul><li>重大事故隐患治理方案内容： <ul><li>一般 -- 生产经营单位车间级负责人或<strong>有关人员立即组织整改</strong></li><li>重大 -- 生产经营单位主要责任人组织制度方案</li></ul></li><li>重大隐患治理方案： <ul><li>目标任务、方法、物资、负责人、时限、预案</li></ul></li><li>事故隐患治理： <ul><li><strong>无法保证安全</strong>撤出作业人人员，并<strong>疏散</strong>可能危及人员，设警<strong>戒标志</strong>，暂停业</li></ul></li></ul><p>自然灾害的预警：</p><ul><li>接到<strong>预警</strong>，向下属发出<strong>预警通知</strong>，发生灾害可能<strong>危及生产经营单位和人员安全</strong>的情况，应<strong>撤离 、停止作业</strong>，并向当地人民政府及<strong>部门报告</strong></li></ul><p>治理后的安全评估：</p><ul><li>评估： 重大事故隐患后，需根据条件评估（有--自己评估、无--委托）</li><li>审查： 部门审查同意</li></ul><p>重大事故隐患治理的监督检查：</p><ul><li>发现安全重大隐患，<strong>下达整改书</strong>，<strong>必要时</strong>报告同级人民政府实行<strong>挂牌督办</strong>；完成申请--<strong>10日内现场审查</strong><ul><li>审查：不合格--改，不改--罚，不具备--关闭</li></ul></li><li>部门<strong>每季</strong>度省，省每<strong>半年</strong>报国务院</li></ul><h3 id="_6-安全生产事故应急预案管理办法-2分" tabindex="-1">6 安全生产事故应急预案管理办法 2分 <a class="header-anchor" href="#_6-安全生产事故应急预案管理办法-2分" aria-label="Permalink to &quot;6 安全生产事故应急预案管理办法 2分&quot;">​</a></h3><h4 id="_6-1-基本规定" tabindex="-1">6.1 基本规定 * <a class="header-anchor" href="#_6-1-基本规定" aria-label="Permalink to &quot;6.1 基本规定 \\*&quot;">​</a></h4><p>应急预案的类型：- 综合应急预案 -- <strong>各种</strong>安全事故 - 专项应急预案 -- 一种或多种<strong>类型</strong>的<strong>专项</strong> - 现场处置方案 -- <strong>具体</strong>应急措施</p><h4 id="_6-2-应急预案的评审与备案" tabindex="-1">6.2 应急预案的评审与备案 ** <a class="header-anchor" href="#_6-2-应急预案的评审与备案" aria-label="Permalink to &quot;6.2 应急预案的评审与备案 \\*\\*&quot;">​</a></h4><p>应急预案的编制：</p><ul><li>根据法规并<strong>结合本单位</strong>编制</li><li><strong>根据法规</strong>或<strong>实际需要</strong>征集意见制度</li></ul><p>应急预案的评审：</p><ul><li>评审： <strong>危金矿 + 烟花爆竹 + 中型单位</strong> -- 评审</li><li>论证： 其他单位论证--<strong>根据自身需要</strong>进行论证</li></ul><p>应急预案的备案：</p><ul><li>部门应急预案： 部门爆政府</li><li>单位应急预案： <ul><li><strong>危建道金矿 + 人密场所</strong>（20个工作日备案） -- 中央（国务院）、中央子公司（省/市）、非（县）</li></ul></li></ul><p>应急预案的修订：</p><ul><li><strong>重大变化</strong>才修订</li></ul><h4 id="_6-3-应急预案的实施" tabindex="-1">6.3 应急预案的实施 ** <a class="header-anchor" href="#_6-3-应急预案的实施" aria-label="Permalink to &quot;6.3 应急预案的实施 \\*\\*&quot;">​</a></h4><p>应急预案演练：</p><ul><li>部门： <strong>每2年</strong></li><li>单位： 综合应急预案和专项应急预案--<strong>每年</strong>1次，现场处置方案--<strong>每半年</strong>1次 / <strong>危建道金矿+人密</strong></li></ul><h3 id="_7-生产安全事故信息报告和处置办法-1分" tabindex="-1">7 生产安全事故信息报告和处置办法 1分 <a class="header-anchor" href="#_7-生产安全事故信息报告和处置办法-1分" aria-label="Permalink to &quot;7 生产安全事故信息报告和处置办法 1分&quot;">​</a></h3><p>较大涉险事故的范围 *</p><ul><li>315 -- 被困、下落不明3人、涉险10人、疏散500人以上、环境严重污染</li></ul><p>事故信息的报告 **</p><ul><li>事故上报: 市、省、国务院部门</li><li>电话快报： 较大及以上 -- 1H</li><li>事故信息的续报： <ul><li>一般、较大事故 -- 每日<strong>1次</strong></li><li>重大、特别重大 -- 每日<strong>2次</strong></li><li>多久时间： <strong>30日内</strong>（<strong>交通、火灾7日内</strong>）</li></ul></li></ul><p>事故信息的处置 *：</p><table tabindex="0"><thead><tr><th style="text-align:center;">判定指标</th><th style="text-align:center;">一般事故</th><th style="text-align:center;">较大事故</th><th style="text-align:center;">重大事故</th><th style="text-align:center;">特别重大事故</th></tr></thead><tbody><tr><td style="text-align:center;">死亡人数</td><td style="text-align:center;">&lt;3人</td><td style="text-align:center;">3~9人</td><td style="text-align:center;">10~29人</td><td style="text-align:center;">≥30人</td></tr><tr><td style="text-align:center;">重伤人数</td><td style="text-align:center;">&lt;10人</td><td style="text-align:center;">10~49人</td><td style="text-align:center;">50~99人</td><td style="text-align:center;">≥100人</td></tr><tr><td style="text-align:center;">直接经济损失</td><td style="text-align:center;">&lt;1000万元</td><td style="text-align:center;">1000万~5000万元</td><td style="text-align:center;">5000万~1亿元</td><td style="text-align:center;">≥1亿元</td></tr><tr><td style="text-align:center;">人员转移</td><td style="text-align:center;">&lt;1万以下</td><td style="text-align:center;">1万~5万人</td><td style="text-align:center;">5万~15万人</td><td style="text-align:center;">≥15万人</td></tr><tr><td style="text-align:center;">事故类型</td><td style="text-align:center;">折断、坠落</td><td style="text-align:center;">爆炸、整体倾斜</td><td style="text-align:center;">600兆瓦锅炉、中断≥24H</td><td style="text-align:center;">600兆瓦锅炉爆炸</td></tr><tr><td style="text-align:center;">滞留时间</td><td style="text-align:center;">12H以下</td><td style="text-align:center;">12H~24H</td><td style="text-align:center;">24H-48H</td><td style="text-align:center;">48H以上</td></tr><tr><td style="text-align:center;">调查部门</td><td style="text-align:center;">县政府</td><td style="text-align:center;">市政府</td><td style="text-align:center;">省政府</td><td style="text-align:center;">国务院</td></tr><tr><td style="text-align:center;">处置部门</td><td style="text-align:center;">县应急</td><td style="text-align:center;">市应急</td><td style="text-align:center;">省应急</td><td style="text-align:center;">国务院应急</td></tr><tr><td style="text-align:center;">上报部门</td><td style="text-align:center;">市应急</td><td style="text-align:center;">省应急</td><td style="text-align:center;">国务院应急</td><td style="text-align:center;">国务院应急</td></tr></tbody></table><h3 id="_8-安全生产严重失信主体名单管理办法" tabindex="-1">8 安全生产严重失信主体名单管理办法 <a class="header-anchor" href="#_8-安全生产严重失信主体名单管理办法" aria-label="Permalink to &quot;8 安全生产严重失信主体名单管理办法&quot;">​</a></h3><h4 id="_8-1-严重失信主体名单的列入条件" tabindex="-1">8.1 严重失信主体名单的列入条件 ** <a class="header-anchor" href="#_8-1-严重失信主体名单的列入条件" aria-label="Permalink to &quot;8.1 严重失信主体名单的列入条件 \\*\\*&quot;">​</a></h4><p>基本规定：</p><ul><li>基本概念： <ul><li><strong>受行政处罚</strong>，并<strong>性质恶劣、情节严重</strong>的行为</li></ul></li><li>管理部门及职责</li></ul><p>列入条件：</p><ul><li>发生事故的列入： ① 重大、特别重大 ② 12月2次以上较大 ③ 情节特别严重、影响特别恶劣 ④ 瞒报、谎报 ⑤ 不作为、擅离职守、逃跑</li><li>没有发生事故列入： ① 未取得安全生产许可证或暂扣、吊销期间继续生产的 ② 虚假证书 ③ 处罚有能力，拒不执行、逃避执法 ④ 其他违法性质恶劣、情节严重</li><li>列入程序 -- 3个工作日录入，20个工作日系统公示</li></ul><h4 id="_8-2-严重失信主体名单的管理措施" tabindex="-1">8.2 严重失信主体名单的管理措施 * <a class="header-anchor" href="#_8-2-严重失信主体名单的管理措施" aria-label="Permalink to &quot;8.2 严重失信主体名单的管理措施 \\*&quot;">​</a></h4><p>管理措施：- 加大执法<strong>检查</strong>频次、<strong>暂停</strong>项目审批 - <strong>取消</strong>评优资格 - 政府资金、支持予以<strong>限制</strong></p><ul><li>移除： -- 条件：</li></ul><p>管理期限： 期限<strong>3年</strong>，满12个月可申请</p><p>移出程序： <strong>履行</strong>处罚义务、<strong>主动</strong>消除危害、未在发生严重失信行为</p><h3 id="_9-建设工程消防设计审查验收管理暂行规定-1分" tabindex="-1">9 建设工程消防设计审查验收管理暂行规定 1分 <a class="header-anchor" href="#_9-建设工程消防设计审查验收管理暂行规定-1分" aria-label="Permalink to &quot;9 建设工程消防设计审查验收管理暂行规定 1分&quot;">​</a></h3><h4 id="_9-1-基本规定" tabindex="-1">9.1 基本规定 ** <a class="header-anchor" href="#_9-1-基本规定" aria-label="Permalink to &quot;9.1 基本规定 \\*\\*&quot;">​</a></h4><p>适用范围:</p><ul><li>不适用： 住宅内装修、村民自建住宅、灾区、临时性等</li></ul><p>有关单位的消防设计、施工质量责任与义务：</p><ul><li>责任 <ul><li>建设单位--<strong>首要</strong>责任</li><li>设计、施工、监理、技术 -- 负<strong>主体</strong>责任</li><li>从业人员 -- 个人责任</li></ul></li></ul><h4 id="_9-2-特殊建设工程的消防设计审查、消防验收" tabindex="-1">9.2 特殊建设工程的消防设计审查、消防验收 * <a class="header-anchor" href="#_9-2-特殊建设工程的消防设计审查、消防验收" aria-label="Permalink to &quot;9.2 特殊建设工程的消防设计审查、消防验收 \\*&quot;">​</a></h4><p>特殊建设工程的消防设计与验收： 必审必验</p><p>特殊建设工程的判定：</p><ul><li>吃喝娱乐500，老弱病残1000，修身养性学诊产2500；</li><li>住1W平、行1.5W平、玩2W平</li></ul><h4 id="_9-3-其他建设工程的消防设计、备案与抽查" tabindex="-1">9.3 其他建设工程的消防设计、备案与抽查 * <a class="header-anchor" href="#_9-3-其他建设工程的消防设计、备案与抽查" aria-label="Permalink to &quot;9.3 其他建设工程的消防设计、备案与抽查 \\*&quot;">​</a></h4><ul><li>备案等抽查：双随机一公开</li></ul><h3 id="_10-高层民用建筑消防安全管理规定-1分" tabindex="-1">10 高层民用建筑消防安全管理规定 1分 <a class="header-anchor" href="#_10-高层民用建筑消防安全管理规定-1分" aria-label="Permalink to &quot;10 高层民用建筑消防安全管理规定 1分&quot;">​</a></h3><h4 id="_10-1-消防安全职责" tabindex="-1">10.1 消防安全职责 * <a class="header-anchor" href="#_10-1-消防安全职责" aria-label="Permalink to &quot;10.1 消防安全职责 \\*&quot;">​</a></h4><p>高层民用建筑定义：</p><ul><li>高层<strong>住宅</strong> -- ＞ <strong>27米</strong></li><li>高层<strong>公共</strong> -- ＞ <strong>24米</strong></li></ul><p>消防安全职责：</p><ul><li><strong>业主、使用人</strong>是高层建筑消<strong>防安全责任主体</strong></li><li><strong>可以委托物业</strong> -- 委托方就需要做好消防安全工作</li><li><strong>两个及以上的业主、使用人</strong> -- 各自负责自己的，公共的共同负责；同一层两个及以上 -- 共同<strong>委托物业</strong>或明确<strong>一个业主、使用人</strong></li></ul><h4 id="_10-2-消防安全管理" tabindex="-1">10.2 消防安全管理 * <a class="header-anchor" href="#_10-2-消防安全管理" aria-label="Permalink to &quot;10.2 消防安全管理 \\*&quot;">​</a></h4><p>施工期间的消防安全管理：</p><ul><li>保险： 国家<strong>鼓励</strong>购买</li><li>责任： 建设单位与施工单位明确消防安全责任</li><li>人员管理： 专人</li><li>人员配备： 超过100m -- 鼓励配注消防工程师</li></ul><p>高层民用建筑的消防安全管理：</p><ul><li>特殊需明火作业需办理<strong>动火审批手续</strong></li></ul><p>高层公共建筑的消防安全管理：</p><ul><li>管理单位实行<strong>24小时</strong>值班制，每班不<strong>少于2名</strong>值班人员</li><li><strong>超过50m的民用</strong>外墙广告不燃材质</li></ul><h4 id="_10-3-宣传教育和疏散" tabindex="-1">10.3 宣传教育和疏散 * <a class="header-anchor" href="#_10-3-宣传教育和疏散" aria-label="Permalink to &quot;10.3 宣传教育和疏散 \\*&quot;">​</a></h4><p>防火巡查、检查：</p><ul><li>巡查 -- 每日巡查，聚集场所<strong>每2小时</strong>，医院、学校、养老院白天晚上</li><li>检查 -- 住宅每月，公共每半月</li></ul><p>消防培训与演练：</p><ul><li>培训： 住宅每年，公共每半年</li><li>演练： 每年，超过100m公共每半年</li></ul><h3 id="_11-工贸企业粉尘防爆安全规定-2-3分" tabindex="-1">11 工贸企业粉尘防爆安全规定 2-3分 <a class="header-anchor" href="#_11-工贸企业粉尘防爆安全规定-2-3分" aria-label="Permalink to &quot;11 工贸企业粉尘防爆安全规定 2-3分&quot;">​</a></h3><h4 id="_11-1-工贸企业粉尘防爆基本规定" tabindex="-1">11.1 工贸企业粉尘防爆基本规定 ** <a class="header-anchor" href="#_11-1-工贸企业粉尘防爆基本规定" aria-label="Permalink to &quot;11.1 工贸企业粉尘防爆基本规定 \\*\\*&quot;">​</a></h4><p>适用范围:</p><p>安全生产责任：</p><ul><li>企业主体责任： 粉尘涉爆企业主要责任人是粉尘涉爆安全第一责任人</li><li>教育培训： 相关从业人员进行防爆<strong>专项</strong>教育和培训</li><li>制定预案并<strong>定期组织演练</strong></li><li>工艺、设备、场所等发生<strong>变更</strong>，需<strong>重新</strong>评估</li></ul><h4 id="_11-2-安全生产保障" tabindex="-1">11.2 安全生产保障 *** <a class="header-anchor" href="#_11-2-安全生产保障" aria-label="Permalink to &quot;11.2 安全生产保障 \\*\\*\\*&quot;">​</a></h4><ul><li><strong>不得单独</strong>才有<strong>隔爆</strong>措施</li><li><strong>禁止</strong>沉降式、巷道式除尘，铝镁等金属应采用<strong>负压</strong>式除尘</li><li>检修： 专项审批--<strong>*防止产生火花</strong>的防爆工具</li></ul><h4 id="_11-3-监督检查" tabindex="-1">11.3 监督检查 * <a class="header-anchor" href="#_11-3-监督检查" aria-label="Permalink to &quot;11.3 监督检查 \\*&quot;">​</a></h4><h3 id="_12-建设项目安全设施-三同时-监督管理办法-3分" tabindex="-1">12 建设项目安全设施“三同时”监督管理办法 3分 <a class="header-anchor" href="#_12-建设项目安全设施-三同时-监督管理办法-3分" aria-label="Permalink to &quot;12 建设项目安全设施“三同时”监督管理办法 3分&quot;">​</a></h3><h4 id="_12-1-安全预评价与设计审查" tabindex="-1">12.1 安全预评价与设计审查 ** <a class="header-anchor" href="#_12-1-安全预评价与设计审查" aria-label="Permalink to &quot;12.1 安全预评价与设计审查 \\*\\*&quot;">​</a></h4><p>《建设项目安全设施“三同时”监督管理办法》</p><ul><li>本办法所称建设项目安全设施是指生产经营单位用于<strong>预防</strong>生产安全事故的设备、设施、装置、构（建）筑物及其他<strong>技术措施</strong>的总称。</li></ul><p>建设项目安全预评价：</p><ul><li>可行性研究时，按规定进行安全预评价：危金矿 + 烟花爆竹（生产、储存） + 使用危品达一定量</li></ul><p>建设项目安全设施设计审查：</p><ul><li>审查程序： <ul><li>申请： 危金矿 + 烟花爆竹（生产、储存）向应急部提出审查申请，其他自己审查</li><li>受理： <strong>5个工作日</strong>受理，书面告知</li><li>做决定: <strong>20个工作日</strong>做决定，不做经部门<strong>负责人同意</strong>，可以延长10个工作日--并告知申请人</li></ul></li><li>设计变更： <ul><li>原批准部门审查同意：① 规模、工艺<strong>重大</strong>变更的； ② 改变安全实施设计 + 可能降低安全性能的；③ 在施工间重新设计的</li></ul></li></ul><h4 id="_12-2-施工和竣工验收" tabindex="-1">12.2 施工和竣工验收 * <a class="header-anchor" href="#_12-2-施工和竣工验收" aria-label="Permalink to &quot;12.2 施工和竣工验收 \\*&quot;">​</a></h4><p>施工：</p><ul><li>方案先行： 对危险性大的部门编制专项施工方案，经<strong>施工单位技术负责人</strong>、<strong>总监理工程师</strong>签字后实施</li></ul><p>验收：</p><ul><li>生产经营单位要检查，竣工验收</li><li><u>危金矿 + 烟花爆竹（生产、储存） + 使用危品达一定量</u> = <strong>机构</strong>进行验收评价 -- 10%</li></ul><p>总结：</p><table tabindex="0"><thead><tr><th style="text-align:center;">建设项目</th><th style="text-align:left;">竣工验收</th><th style="text-align:left;">验收评价</th><th style="text-align:left;">设计审查、部门核查</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>危金矿烟</strong></td><td style="text-align:left;">生产经营单位</td><td style="text-align:left;">安全评价机构</td><td style="text-align:left;">应急管理部门</td></tr><tr><td style="text-align:center;"><strong>化工</strong></td><td style="text-align:left;">生产经营单位</td><td style="text-align:left;">安全评价机构</td><td style="text-align:left;">——</td></tr><tr><td style="text-align:center;"><strong>其他</strong></td><td style="text-align:left;">生产经营单位</td><td style="text-align:left;">——</td><td style="text-align:left;">——</td></tr></tbody></table><p>试运行：</p><ul><li>时间： 根据建设项目<strong>需要</strong>，20~180日</li><li>备案： <strong>化学品</strong>（生、储）建设和<strong>化工</strong>建设项目报应急部门</li></ul><h3 id="_13-危险化学品输送管道安全管理规定-1分" tabindex="-1">13 危险化学品输送管道安全管理规定 1分 <a class="header-anchor" href="#_13-危险化学品输送管道安全管理规定-1分" aria-label="Permalink to &quot;13 危险化学品输送管道安全管理规定 1分&quot;">​</a></h3><h4 id="_13-1-危险化学品管道的规划与建设" tabindex="-1">13.1 危险化学品管道的规划与建设 ** <a class="header-anchor" href="#_13-1-危险化学品管道的规划与建设" aria-label="Permalink to &quot;13.1 危险化学品管道的规划与建设 \\*\\*&quot;">​</a></h4><p>适用范围：</p><ul><li>适用： 危险化学品（生、储）的单位在<strong>厂区外</strong></li><li>不适用： 油、气管道不适用</li></ul><p>危险化学品管道的规划：</p><ul><li><strong>剧毒（光气、氯气）禁止</strong>公共区域</li><li><strong>有毒（氨、硫化氢）严格控制</strong>公共区域</li><li>地质灾害避开，无法避开就采取可靠工程措施</li></ul><p>危险化学品管道的建设：</p><ul><li>试压<strong>半年后</strong>未投入使用，需重新进行<strong>气密性试验</strong></li></ul><h4 id="_13-2-危险化学品管道运行" tabindex="-1">13.2 危险化学品管道运行 ** <a class="header-anchor" href="#_13-2-危险化学品管道运行" aria-label="Permalink to &quot;13.2 危险化学品管道运行 \\*\\*&quot;">​</a></h4><p>一般要求：</p><ul><li><strong>专人</strong>日常<strong>巡护</strong>，发现<strong>报告单位</strong>负责人</li><li>及时排除，<strong>有困难</strong>的外部原因，应向当地<strong>应急管理部门</strong>报告</li><li><strong>禁止</strong>在管道上建设电力、通信线路</li><li><strong>先制止、无法处置</strong>在向应急部门报告（破坏、有损管道）</li></ul><p>距离相关要求：</p><ul><li><strong>种植、挖掘、修建</strong>（5米内），先制止、无在报告</li><li>生活、加油气、电站（5米内）报告</li><li>施工单位<strong>7日前</strong>书面通知管道单位，并<strong>共同</strong>制定应急预案，管道派<strong>专人</strong>现场指导（200m）</li><li>穿河、专用隧道（1000m）抛锚、挖沙、爆破、采石</li></ul><h3 id="_14-危险化学品重大危险源监督管理暂行规定-3分" tabindex="-1">14 危险化学品重大危险源监督管理暂行规定 3分 <a class="header-anchor" href="#_14-危险化学品重大危险源监督管理暂行规定-3分" aria-label="Permalink to &quot;14 危险化学品重大危险源监督管理暂行规定 3分&quot;">​</a></h3><h4 id="_14-1-辨识与评估" tabindex="-1">14.1 辨识与评估 ** <a class="header-anchor" href="#_14-1-辨识与评估" aria-label="Permalink to &quot;14.1 辨识与评估 \\*\\*&quot;">​</a></h4><p>重大危险源的分级与评估:</p><ul><li>等级： 等级1~4，1最高</li><li>评估： <ul><li>可自己可委托单位（具有资质）</li><li>安全评价可代替安全评估，也可单独评估</li><li>找机构: <ul><li>1~2级重大危险源 + 剧毒≥1</li><li>1级重大危险源 + 爆炸品或液化易燃气体≥1</li></ul></li></ul></li></ul><p>重大危险源重新辩识：</p><ul><li>满三年、新改扩建、发生变化、人员死亡（伤10）</li></ul><h4 id="_14-2-安全管理" tabindex="-1">14.2 安全管理 *** <a class="header-anchor" href="#_14-2-安全管理" aria-label="Permalink to &quot;14.2 安全管理 \\*\\*\\*&quot;">​</a></h4><p>监控体系：</p><ul><li>不间断采集和监控，级功能（记录、预警、存储）；<strong>1~2级</strong>具备<strong>紧急停车</strong>功能，电子数据保存不<strong>少于30天</strong> -** 毒性气体、液化气体、剧毒液体**（1~2）配备<strong>独立的安全仪表系统</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;">重大危险源</th><th style="text-align:center;">紧<em>急切</em>断</th><th style="text-align:center;">独立仪<em>表</em>（一、二级）</th><th style="text-align:center;">泄<em>漏</em>物紧急处置</th></tr></thead><tbody><tr><td style="text-align:center;"><em>毒</em>性气体</td><td style="text-align:center;">√</td><td style="text-align:center;">√</td><td style="text-align:center;">√</td></tr><tr><td style="text-align:center;"><em>剧</em>毒液体</td><td style="text-align:center;">√</td><td style="text-align:center;">√</td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;"><em>易</em>燃气体</td><td style="text-align:center;">√</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td style="text-align:center;"><em>液</em>化气体</td><td style="text-align:center;"></td><td style="text-align:center;">√</td><td style="text-align:center;"></td></tr></tbody></table><p>装备的配备：</p><ul><li>剧毒服两套以上</li></ul><p>应急预案演练：</p><ul><li>专项应急预案，每年一次</li><li>现场处置方案，每半年</li></ul><p>重大危险源建档与备案 备案： 单位（15天） -- 县（每季、1~2级） -- 市(半年1级) -- 省</p><h4 id="_14-3-监督检查" tabindex="-1">14.3 监督检查 * <a class="header-anchor" href="#_14-3-监督检查" aria-label="Permalink to &quot;14.3 监督检查 \\*&quot;">​</a></h4><p>重大危险源的核销： 核销: 单位 -- 县部门（每季、核销、1~2级、30日） -- 市(半年1级) -- 省</p><h3 id="_15-工贸企业有限空间作业安全管理与监督暂行规定-3分" tabindex="-1">15 工贸企业有限空间作业安全管理与监督暂行规定 3分 <a class="header-anchor" href="#_15-工贸企业有限空间作业安全管理与监督暂行规定-3分" aria-label="Permalink to &quot;15 工贸企业有限空间作业安全管理与监督暂行规定 3分&quot;">​</a></h3><h4 id="_15-1-有限空间作业的安全保障" tabindex="-1">15.1 有限空间作业的安全保障 ** <a class="header-anchor" href="#_15-1-有限空间作业的安全保障" aria-label="Permalink to &quot;15.1 有限空间作业的安全保障 \\*\\*&quot;">​</a></h4><p>适用范围</p><p>工贸企业的安全责任：</p><ul><li>分包 -- 工贸企业统一协调、管理，并安全检查、督促</li><li>培训： 每年一次培训并记录，不合格不得作业</li><li>台账国家鼓励</li></ul><p>人员责任:</p><ul><li>审批： 对于存在<strong>硫化氢、一氧化碳、二氧化碳</strong>等中毒和窒息风险的有限空间作业，应由工<strong>贸企业主要负责人</strong>或其<strong>书面委托人员</strong>审批；委托审批的，责任仍由<strong>主要负责人承担</strong>。</li><li>监护人员： <ul><li>专职或兼职</li><li>作业前逐项检查</li><li>作业中全程进行监护作业，监护人不得进入现场作业或指导</li><li>发生事故监护人立即组织撤离，发生没做好措施得制止</li></ul></li></ul><p>安全措施：</p><ul><li>原则： 先通风、再检测、后作业</li><li>作业前： 具备条件放置告知牌，隔离防止进入，作业前监护人才解除</li><li>作业中： 专人通风并持续检查浓度，中断应重新通风及检测才可进入</li></ul><h4 id="_15-2-有限空间作业的安全监督管理" tabindex="-1">15.2 有限空间作业的安全监督管理 * <a class="header-anchor" href="#_15-2-有限空间作业的安全监督管理" aria-label="Permalink to &quot;15.2 有限空间作业的安全监督管理 \\*&quot;">​</a></h4><p>重点检测范围： 硫化氢、一氧化碳、二氧化碳等易窒息得有限作业空间</p><p>隐患处理： 发现重大安事故隐患整改，无法保证安全--停业撤人，排除后审查同意再作业</p><h3 id="_16-安全生产违法行为行政处罚办法" tabindex="-1">16 安全生产违法行为行政处罚办法 <a class="header-anchor" href="#_16-安全生产违法行为行政处罚办法" aria-label="Permalink to &quot;16 安全生产违法行为行政处罚办法&quot;">​</a></h3><h4 id="_16-1-行政处罚的种类和管辖" tabindex="-1">16.1 行政处罚的种类和管辖 <a class="header-anchor" href="#_16-1-行政处罚的种类和管辖" aria-label="Permalink to &quot;16.1 行政处罚的种类和管辖&quot;">​</a></h4><p>行政处罚的种类：</p><h4 id="_16-2-行政处罚的程序" tabindex="-1">16.2 行政处罚的程序 <a class="header-anchor" href="#_16-2-行政处罚的程序" aria-label="Permalink to &quot;16.2 行政处罚的程序&quot;">​</a></h4><p>听证时限： 当事人5日内提出听证，应急部门<strong>15日内</strong>举行听证，并在进行前7日通知 延期： 可<strong>延期一次</strong></p><p>中止、终止： 暂停、结束 免费听证，原则公开，特殊除外</p><h4 id="_16-3-行政处罚的适用" tabindex="-1">16.3 行政处罚的适用 <a class="header-anchor" href="#_16-3-行政处罚的适用" aria-label="Permalink to &quot;16.3 行政处罚的适用&quot;">​</a></h4><p>同事情不能多次处罚，同一件事多个项目按数额高的罚款，多个违法分别裁量、合并处罚</p>`,604)]))}const b=l(n,[["render",o]]);export{c as __pageData,b as default};
